                "ko": "공격적으로 변하는 조끼. 지니게 하면 특수방어가 올라가지만 변화 기술을 쓸 수 없게 된다.",
                "en": "An item to be held by a Pokémon. This offensive vest raises Sp. Def but prevents the use of status moves.",
                "ja": "こうげきてきに　なる　チョッキ。　もたせると　とくぼうが　あがるが　へんかわざを　だせなくなる。",
                "es": "Chaleco que potencia la Defensa Especial del Pokémon que lo lleva, pero le impide lanzar movimientos de estado.",
                "fr": "Objet à tenir. Une veste augmentant la Défense Spéciale, mais empêchant d’utiliser des capacités de statut.",
                "de": "Trägt ein Pokémon diese Weste, erhöht sich seine Spezial-Verteidigung, aber es kann keine Status-Attacken mehr einsetzen.",
            ]),
        "eviolite": Entry(appOriginalLanguages: [],
            names: ["ko": "진화의휘석", "en": "Eviolite", "ja": "しんかのきせき", "es": "Mineral Evol", "fr": "Évoluroc", "de": "Evolith"],
            texts: [
                "ko": "진화의 이상한 덩어리. 지니게 하면 진화 전 포켓몬의 방어와 특수방어가 올라간다.",
                "en": "A mysterious evolutionary lump. When held by a Pokémon that can still evolve, it raises both Defense and Sp. Def.",
                "ja": "しんかの　ふしぎな　かたまり。　もたせると　しんかまえ　ポケモンの　ぼうぎょと　とくぼうが　あがる。",
                "es": "Roca misteriosa. El Pokémon portador aumentará su Defensa y su Defensa Especial si aún puede evolucionar.",
                "fr": "Objet à tenir. Un étrange concentré d’évolution qui augmente la Défense et la Défense Spéciale d’un Pokémon pouvant évoluer.",
                "de": "Ein mysteriöser Klumpen, der die Verteidigung und Spezial-Verteidigung von Pokémon erhöht, die sich noch entwickeln können.",
            ]),
        "rocky-helmet": Entry(appOriginalLanguages: [],
            names: ["ko": "울퉁불퉁멧", "en": "Rocky Helmet", "ja": "ゴツゴツメット", "es": "Casco Dentado", "fr": "Casque Brut", "de": "Beulenhelm"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 타격 기술을 당했을 때 상대에게도 데미지를 준다.",
                "en": "An item to be held by a Pokémon. If the holder is hit, the attacker will also be damaged upon contact.",
                "ja": "ポケモンに　もたせると　だげきわざを　うけたとき　あいてにも　ダメージを　あたえる。",
                "es": "Si el portador es alcanzado por un movimiento de contacto, el agresor también recibe daño.",
                "fr": "Objet à tenir. Inflige des dégâts à l’attaquant si ce dernier utilise une capacité qui atteint directement le porteur.",
                "de": "Wird der Träger von einer physischen Attacke getroffen, erleidet der Angreifer ebenfalls Schaden.",
            ]),
        "sitrus-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "자뭉열매", "en": "Sitrus Berry", "ja": "オボンのみ", "es": "Baya Zidra", "fr": "Baie Sitrus", "de": "Tsitrubeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 HP를 조금 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can restore its own HP by a small amount during battle.",
                "ja": "ポケモンに　もたせると　ＨＰを　すこしだけ　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para restaurar algunos PS.",
                "fr": "Une Baie qui restaure quelques PV lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, füllt diese seine KP ein wenig auf.",
            ]),
        "lum-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "리샘열매", "en": "Lum Berry", "ja": "ラムのみ", "es": "Baya Ziuela", "fr": "Baie Prine", "de": "Prunusbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 모든 상태 이상을 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can recover from any status condition during battle.",
                "ja": "ポケモンに　もたせると　すべての　じょうたい　いじょうを　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para recuperarse de problemas de estado.",
                "fr": "Une Baie qui soigne toutes les altérations de statut lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, hebt sie alle seine Statusprobleme auf.",
            ]),
        "white-herb": Entry(appOriginalLanguages: [],
            names: ["ko": "하양허브", "en": "White Herb", "ja": "しろいハーブ", "es": "Hierba Blanca", "fr": "Herbe Blanche", "de": "Schlohkraut"],
            texts: [
                "ko": "지니게 한 포켓몬의 능력이 떨어졌을 때 한 번만 원래 상태로 돌아온다.",
                "en": "An item to be held by a Pokémon. It will restore any lowered stat in battle. It can be used only once.",
                "ja": "もたせた　ポケモンの　のうりょくが　さがったとき　いちどだけ　もとの　じょうたいに　もどす。",
                "es": "Restaura cualquier característica reducida en combate. Solo se puede usar una vez. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Restaure les stats qui ont subi une baisse. Ne peut être utilisé qu’une fois.",
                "de": "Ein Item, das einem Pokémon zum Tragen gegeben werden kann. Es hebt einmalig jede negative Statusveränderung auf.",
            ]),
        "black-sludge": Entry(appOriginalLanguages: [],
            names: ["ko": "검은오물", "en": "Black Sludge", "ja": "くろいヘドロ", "es": "Lodo Negro", "fr": "Boue Noire", "de": "Giftschleim"],
            texts: [
                "ko": "지니게 하면 독타입의 포켓몬은 조금씩 HP를 회복한다. 그 이외의 타입은 HP가 줄어 버린다.",
                "en": "An item to be held by a Pokémon. It gradually restores HP to Poison-type Pokémon. It damages any other type.",
                "ja": "もたせると　どくタイプの　ポケモンは　すこしずつ　ＨＰを　かいふくする。　それいがいは　ＨＰが　へってしまう。",
                "es": "Si lo lleva un Pokémon de tipo Veneno, restaura gradualmente sus PS durante el combate. Si es de otro tipo, sus PS se reducirán.",
                "fr": "Objet à tenir. Restaure peu à peu les PV des Pokémon de type Poison. Inflige des dégâts à tous les autres types.",
                "de": "Ein Item zum Tragen, das einem Gift-Pokémon nach und nach KP zurückgibt, anderen Pokémon aber Schaden zufügt.",
            ]),
        "shell-bell": Entry(appOriginalLanguages: [],
            names: ["ko": "조개껍질방울", "en": "Shell Bell", "ja": "かいがらのすず", "es": "Cascabel Concha", "fr": "Grelot Coque", "de": "Muschelglocke"],
            texts: [
                "ko": "지니게 한 포켓몬이 공격하여 상대에게 데미지를 줬을 때 HP를 조금 회복할 수 있다.",
                "en": "An item to be held by a Pokémon. The holder restores a little HP every time it inflicts damage on others.",
                "ja": "もたせた　ポケモンが　こうげきして　あいてに　ダメージを　あたえたとき　ＨＰを　すこし　かいふく　できる。",
                "es": "Debe llevarlo un Pokémon. Cada vez que este inflige daño, recupera algunos PS.",
                "fr": "Objet à tenir. Restaure un peu les PV du porteur chaque fois qu’il inflige des dégâts.",
                "de": "Ein Item zum Tragen. Es stellt einige KP des Trägers immer dann wieder her, wenn dieser dem Ziel Schaden zufügt.",
            ]),
        "big-root": Entry(appOriginalLanguages: [],
            names: ["ko": "큰뿌리", "en": "Big Root", "ja": "おおきなねっこ", "es": "Raíz Grande", "fr": "Grosse Racine", "de": "Großwurzel"],
            texts: [
                "ko": "지니게 하면 HP 흡수 기술을 썼을 때 여느 때보다 많은 HP를 자신이 회복할 수 있다.",
                "en": "An item to be held by a Pokémon. It boosts the amount of HP the holder restores from HP-stealing moves.",
                "ja": "もたせると　ＨＰを　すいとる　わざで　いつもより　おおく　じぶんの　ＨＰを　かいふくできる。",
                "es": "El Pokémon que la lleva recupera más PS al usar movimientos que drenan al objetivo.",
                "fr": "Objet à tenir. Augmente la puissance des capacités volant des PV.",
                "de": "Ein Item zum Tragen. Verstärkt KP-stehlende Attacken.",
            ]),
        "muscle-band": Entry(appOriginalLanguages: [],
            names: ["ko": "힘의머리띠", "en": "Muscle Band", "ja": "ちからのハチマキ", "es": "Cinta Fuerte", "fr": "Bandeau Muscle", "de": "Muskelband"],
            texts: [
                "ko": "힘이 끓어오르는 머리띠. 지니게 하면 물리 기술의 위력이 조금 올라간다.",
                "en": "An item to be held by a Pokémon. This headband exudes strength, slightly boosting the power of physical moves.",
                "ja": "ちからが　わいてくる　ハチマキ。　もたせると　ぶつりわざの　いりょくが　すこし　あがる。",
                "es": "Cinta del pelo que aumenta ligeramente la potencia de los ataques físicos. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un bandeau qui augmente légèrement la puissance des capacités physiques.",
                "de": "Ein Item zum Tragen. Dieses Stirnband verstärkt physische Attacken etwas.",
            ]),
        "wise-glasses": Entry(appOriginalLanguages: [],
            names: ["ko": "박식안경", "en": "Wise Glasses", "ja": "ものしりメガネ", "es": "Gafas Especiales", "fr": "Lunettes Sages", "de": "Schlaubrille"],
            texts: [
                "ko": "두꺼운 렌즈를 붙인 안경. 지니게 하면 특수 기술의 위력이 조금 올라간다.",
                "en": "An item to be held by a Pokémon. This thick pair of glasses slightly boosts the power of special moves.",
                "ja": "ぶあつい　レンズの　ついた　メガネ。　もたせると　とくしゅわざの　いりょくが　すこし　あがる。",
                "es": "Potencian ligeramente los ataques especiales. Debe llevarlas un Pokémon.",
                "fr": "Objet à tenir. Une paire de lunettes épaisses qui augmente légèrement la puissance des capacités spéciales.",
                "de": "Ein Item zum Tragen. Diese dicke Brille verstärkt auf Spezial-Angriff basierende Attacken.",
            ]),
        "scope-lens": Entry(appOriginalLanguages: [],
            names: ["ko": "초점렌즈", "en": "Scope Lens", "ja": "ピントレンズ", "es": "Periscopio", "fr": "Lentilscope", "de": "Scope-Linse"],
            texts: [
                "ko": "약점이 보이는 렌즈. 지니게 한 포켓몬의 기술이 급소에 맞기 쉬워진다.",
                "en": "An item to be held by a Pokémon. It’s a lens for scoping out weak points. It boosts the holder’s critical-hit ratio.",
                "ja": "じゃくてんが　みえる　レンズ。　もたせた　ポケモンの　わざが　きゅうしょに　あたりやすくなる。",
                "es": "Su lente aumenta la probabilidad que tiene el Pokémon que lo lleva de conseguir un golpe crítico.",
                "fr": "Objet à tenir. Une lentille qui augmente le taux de critiques du porteur.",
                "de": "Ein Item, das einem Pokémon zum Tragen gegeben werden kann. Es erhöht die Volltrefferquote.",
            ]),
        "quick-claw": Entry(appOriginalLanguages: [],
            names: ["ko": "선제공격손톱", "en": "Quick Claw", "ja": "せんせいのツメ", "es": "Garra Rápida", "fr": "Vive Griffe", "de": "Flinkklaue"],
            texts: [
                "ko": "가볍고 날카로운 손톱. 지니게 하면 상대보다 먼저 행동할 수도 있다.",
                "en": "An item to be held by a Pokémon. This light, sharp claw lets the bearer move first occasionally.",
                "ja": "かるくて　するどい　ツメ。　もたせると　あいてより　さきに　こうどう　できることが　ある。",
                "es": "Garra ligera y afilada que permite que el Pokémon que la lleve ataque a veces el primero.",
                "fr": "Objet à tenir. Une griffe légère mais tranchante qui permet parfois de frapper en priorité.",
                "de": "Ein Item, das einem Pokémon zum Tragen gegeben werden kann. Es ermöglicht gelegentlich den Erstschlag.",
            ]),
        "bright-powder": Entry(appOriginalLanguages: [],
            names: ["ko": "반짝가루", "en": "Bright Powder", "ja": "ひかりのこな", "es": "Polvo Brillo", "fr": "Poudre Claire", "de": "Blendpuder"],
            texts: [
                "ko": "반짝반짝 빛나는 가루. 지니게 하면 빛이 상대를 혼란시켜 기술이 명중되기 어려워진다.",
                "en": "An item to be held by a Pokémon. It casts a tricky glare that lowers the opposing Pokémon’s accuracy.",
                "ja": "キラキラ　ひかるこな。　もたせると　ひかりが　あいてを　まどわして　わざが　めいちゅう　しにくくなる。",
                "es": "Lanza un destello que baja la Precisión del enemigo. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Intimide l’ennemi et baisse sa Précision.",
                "de": "Ein Item, das einem Pokémon zum Tragen gegeben werden kann. Es senkt die Genauigkeit des Gegners.",
            ]),
        "wide-lens": Entry(appOriginalLanguages: [],
            names: ["ko": "광각렌즈", "en": "Wide Lens", "ja": "こうかくレンズ", "es": "Lupa", "fr": "Loupe", "de": "Großlinse"],
            texts: [
                "ko": "물건이 크게 보이는 렌즈. 지니게 하면 기술의 명중률이 조금 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a magnifying lens that slightly boosts the accuracy of moves.",
                "ja": "ものが　おおきく　みえる　レンズ。　もたせると　わざの　めいちゅうりつが　すこし　あがる。",
                "es": "Debe llevarla un Pokémon. Aumenta ligeramente la precisión de los movimientos.",
                "fr": "Objet à tenir. Une loupe qui augmente légèrement la Précision des capacités.",
                "de": "Ein Item zum Tragen. Dieses Vergrößerungsglas erhöht die Genauigkeit etwas.",
            ]),
        "weakness-policy": Entry(appOriginalLanguages: [],
            names: ["ko": "약점보험", "en": "Weakness Policy", "ja": "じゃくてんほけん", "es": "Seguro Debilidad", "fr": "Vulné-Assurance", "de": "Schwächenschutz"],
            texts: [
                "ko": "약점을 공격당했을 때 공격과 특수공격이 각각 크게 올라간다.",
                "en": "An item to be held by a Pokémon. Attack and Sp. Atk sharply increase if the holder is hit with a move it’s weak to.",
                "ja": "じゃくてんを　つかれたとき　こうげきと　とくこうが　それぞれ　ぐーんと　あがる。",
                "es": "Aumenta mucho el Ataque y el Ataque Especial cuando el Pokémon que lo lleva recibe un ataque frente al cual es débil.",
                "fr": "Objet à tenir. Augmente beaucoup l’Attaque et l’Attaque Spéciale du Pokémon lorsqu’il est touché par une capacité d’un type auquel il est vulnérable.",
                "de": "Erhöht den Angriff und den Spezial-Angriff des Trägers stark, wenn er von einer sehr effektiven Attacke getroffen wird.",
            ]),
        "focus-band": Entry(appOriginalLanguages: [],
            names: ["ko": "기합의머리띠", "en": "Focus Band", "ja": "きあいのハチマキ", "es": "Cinta Aguante", "fr": "Bandeau", "de": "Fokusband"],
            texts: [
                "ko": "지니게 하면 기절할 듯한 기술을 받아도 HP를 1 남겨서 견디기도 한다.",
                "en": "An item to be held by a Pokémon. The holder may endure a potential KO attack, leaving it with just 1 HP.",
                "ja": "もたせると　ひんしに　なりそうな　わざを　うけても　ＨＰを　１だけ　のこして　たえることが　ある。",
                "es": "El Pokémon que la lleva puede resistir un golpe que potencialmente lo dejaría K. O. y se queda con 1 PS.",
                "fr": "Objet à tenir pouvant parfois empêcher d’être mis K.O., ne laissant qu’un seul PV.",
                "de": "Ein Item, das die Kampfunfähigkeit verhindern kann, da dem Träger 1 KP bleibt.",
            ]),
        "flame-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "화염구슬", "en": "Flame Orb", "ja": "かえんだま", "es": "Llamasfera", "fr": "Orbe Flamme", "de": "Heiß-Orb"],
            texts: [
                "ko": "만지면 열을 내는 이상한 구슬. 지니게 하면 배틀 중에 화상 상태가 된다.",
                "en": "An item to be held by a Pokémon. It’s a bizarre orb that will afflict the holder with a burn during battle.",
                "ja": "さわると　ねつをだす　ふしぎなたま。　もたせると　せんとうちゅうに　やけどの　じょうたいに　なる。",
                "es": "Extraña esfera que causa quemaduras al Pokémon que la lleva en combate.",
                "fr": "Objet à tenir. Un orbe bizarre qui brûle son porteur durant le combat.",
                "de": "Ein Item zum Tragen. Dieser bizarre Orb fügt seinem Träger Verbrennungen zu.",
            ]),
        "toxic-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "맹독구슬", "en": "Toxic Orb", "ja": "どくどくだま", "es": "Toxisfera", "fr": "Orbe Toxique", "de": "Toxik-Orb"],
            texts: [
                "ko": "만지면 독을 발산하는 이상한 구슬. 지니게 하면 배틀 중에 맹독 상태가 된다.",
                "en": "An item to be held by a Pokémon. It’s a bizarre orb that will badly poison the holder during battle.",
                "ja": "さわると　どくをだす　ふしぎなたま。　もたせると　せんとうちゅうに　もうどくの　じょうたいに　なる。",
                "es": "Extraña esfera que envenena gravemente al Pokémon que la lleva en combate.",
                "fr": "Objet à tenir. Un orbe bizarre qui empoisonne gravement son porteur durant le combat.",
                "de": "Ein Item zum Tragen. Dieser bizarre Orb vergiftet seinen Träger im Kampf schwer.",
            ]),
        "mystic-water": Entry(appOriginalLanguages: [],
            names: ["ko": "신비의물방울", "en": "Mystic Water", "ja": "しんぴのしずく", "es": "Agua Mística", "fr": "Eau Mystique", "de": "Zauberwasser"],
            texts: [
                "ko": "물방울 모양의 보석. 지니게 하면 물타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This teardrop-shaped gem boosts the power of Water-type moves.",
                "ja": "しずくの　かたちの　ほうせき。　もたせると　みずタイプの　わざの　いりょくが　あがる。",
                "es": "Gema con forma de gota de agua que fortalece los movimientos de tipo Agua. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Une gemme en forme de goutte d’eau qui augmente la puissance des capacités de type Eau.",
                "de": "Ein Item zum Tragen. Ein tränenförmiger Edelstein, der Attacken vom Typ Wasser verstärkt.",
            ]),
        "miracle-seed": Entry(appOriginalLanguages: [],
            names: ["ko": "기적의씨", "en": "Miracle Seed", "ja": "きせきのタネ", "es": "Semilla Milagro", "fr": "Graine Miracle", "de": "Wundersaat"],
            texts: [
                "ko": "생명이 깃든 씨앗. 지니게 하면 풀타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a seed imbued with life-force that boosts the power of Grass-type moves.",
                "ja": "せいめいが　やどる　タネ。　もたせると　くさタイプの　わざの　いりょくが　あがる。",
                "es": "Debe llevarla un Pokémon. La vitalidad de la semilla fortalece los movimientos de tipo Planta.",
                "fr": "Objet à tenir. Une graine remplie de vie qui augmente la puissance des capacités de type Plante.",
                "de": "Ein Item zum Tragen. Ein Samen voller Lebenskraft, der Attacken vom Typ Pflanze verstärkt.",
            ]),
        "magnet": Entry(appOriginalLanguages: [],
            names: ["ko": "자석", "en": "Magnet", "ja": "じしゃく", "es": "Imán", "fr": "Aimant", "de": "Magnet"],
            texts: [
                "ko": "강력한 자석. 지니게 하면 전기타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a powerful magnet that boosts the power of Electric-type moves.",
                "ja": "きょうりょくな　じしゃく。　もたせると　でんきタイプの　わざの　いりょくが　あがる。",
                "es": "Debe llevarlo un Pokémon. Su potente magnetismo fortalece los movimientos de tipo Eléctrico.",
                "fr": "Objet à tenir. Un aimant puissant qui augmente la puissance des capacités de type Électrik.",
                "de": "Ein Item zum Tragen, dessen magnetische Kraft Attacken vom Typ Elektro verstärkt.",
            ]),
        "never-melt-ice": Entry(appOriginalLanguages: [],
            names: ["ko": "녹지않는얼음", "en": "Never-Melt Ice", "ja": "とけないこおり", "es": "Hielo Perpetuo", "fr": "Glace Éternelle", "de": "Ewiges Eis"],
            texts: [
                "ko": "열을 가까이하지 않게 하는 얼음. 지니게 하면 얼음타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a heat- repelling piece of ice that boosts the power of Ice-type moves.",
                "ja": "ねつを　よせつけない　こおり。　もたせると　こおりタイプの　わざの　いりょくが　あがる。",
                "es": "Fragmento de hielo que repele el calor y fortalece los movimientos de tipo Hielo. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un morceau de glace qui réfléchit la chaleur et augmente la puissance des capacités de type Glace.",
                "de": "Ein Item zum Tragen. Ein Stück Eis, das Hitze fernhält und Attacken vom Typ Eis verstärkt.",
            ]),
        "black-belt": Entry(appOriginalLanguages: [],
            names: ["ko": "검은띠", "en": "Black Belt", "ja": "くろおび", "es": "Cinturón Negro", "fr": "Ceinture Noire", "de": "Schwarzgurt"],
            texts: [
                "ko": "마음을 긴장시키는 띠. 지니게 하면 격투타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This belt helps the wearer to focus and boosts the power of Fighting-type moves.",
                "ja": "きが　ひきしまる　おび。　もたせると　かくとうタイプの　わざの　いりょくが　あがる。",
                "es": "Debe llevarlo un Pokémon. Aumenta la concentración y fortalece los movimientos de tipo Lucha.",
                "fr": "Objet à tenir. Une ceinture d’art martial qui augmente la puissance des capacités de type Combat.",
                "de": "Ein Item zum Tragen. Ein Gürtel, der die Entschlossenheit sowie Attacken vom Typ Kampf verstärkt.",
            ]),
        "poison-barb": Entry(appOriginalLanguages: [],
            names: ["ko": "독바늘", "en": "Poison Barb", "ja": "どくバリ", "es": "Flecha Venenosa", "fr": "Pic Venin", "de": "Giftstich"],
            texts: [
                "ko": "독이 있는 작은 침. 지니게 하면 독타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This small, poisonous barb boosts the power of Poison-type moves.",
                "ja": "どくのある　ちいさな　ハリ。　もたせると　どくタイプの　わざの　いりょくが　あがる。",
                "es": "Flecha venenosa que refuerza los movimientos de tipo Veneno. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un petit pic empoisonné qui augmente la puissance des capacités de type Poison.",
                "de": "Ein Item zum Tragen. Ein schmaler und giftiger Widerhaken, der Attacken vom Typ Gift verstärkt.",
            ]),
        "soft-sand": Entry(appOriginalLanguages: [],
            names: ["ko": "부드러운모래", "en": "Soft Sand", "ja": "やわらかいすな", "es": "Arena Fina", "fr": "Sable Doux", "de": "Pudersand"],
            texts: [
                "ko": "만지면 보슬보슬한 모래. 지니게 하면 땅타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a loose, silky sand that boosts the power of Ground-type moves.",
                "ja": "さわると　サラサラする　すな。　もたせると　じめんタイプの　わざの　いりょくが　あがる。",
                "es": "Debe llevarla un Pokémon. La suavidad de la arena fortalece los movimientos de tipo Tierra.",
                "fr": "Objet à tenir. Du sable fin et soyeux qui augmente la puissance des capacités de type Sol.",
                "de": "Ein Item zum Tragen. Samtiger Sand, der Attacken vom Typ Boden verstärkt.",
            ]),
        "sharp-beak": Entry(appOriginalLanguages: [],
            names: ["ko": "예리한부리", "en": "Sharp Beak", "ja": "するどいくちばし", "es": "Pico Afilado", "fr": "Bec Pointu", "de": "Spitzer Schnabel"],
            texts: [
                "ko": "길고 뾰족한 부리. 지니게 하면 비행타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a long, sharp beak that boosts the power of Flying-type moves.",
                "ja": "ながく　とがった　くちばし。　もたせると　ひこうタイプの　わざの　いりょくが　あがる。",
                "es": "Pico largo y afilado que aumenta la potencia de los movimientos de tipo Volador. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un bec long et pointu qui augmente la puissance des capacités de type Vol.",
                "de": "Ein Item zum Tragen. Ein langer, scharfer Schnabel verstärkt Attacken vom Typ Flug.",
            ]),
        "twisted-spoon": Entry(appOriginalLanguages: [],
            names: ["ko": "휘어진스푼", "en": "Twisted Spoon", "ja": "まがったスプーン", "es": "Cuchara Torcida", "fr": "Cuillère Tordue", "de": "Krummlöffel"],
            texts: [
                "ko": "염동력을 담은 숟가락. 지니게 하면 에스퍼타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This spoon is imbued with telekinetic power and boosts Psychic-type moves.",
                "ja": "ねんりきを　こめた　スプーン。　もたせると　エスパータイプの　わざの　いりょくが　あがる。",
                "es": "Cuchara imbuida de energía telequinética que potencia los movimientos de tipo Psíquico. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Une cuillère contenant un pouvoir télékinétique qui augmente la puissance des capacités de type Psy.",
                "de": "Ein Item zum Tragen. Ein Löffel voller telekinetischer Energie, der Attacken vom Typ Psycho verstärkt.",
            ]),
        "silver-powder": Entry(appOriginalLanguages: [],
            names: ["ko": "은빛가루", "en": "Silver Powder", "ja": "ぎんのこな", "es": "Polvo Plata", "fr": "Poudre Argentée", "de": "Silberstaub"],
            texts: [
                "ko": "은색으로 반짝이는 가루. 지니게 하면 벌레타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a shiny silver powder that will boost the power of Bug-type moves.",
                "ja": "ぎんいろに　かがやく　こな。　もたせると　むしタイプの　わざの　いりょくが　あがる。",
                "es": "Polvo de brillo argénteo que fortalece los ataques de tipo Bicho. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. De la poudre d’argent brillante qui augmente la puissance des capacités de type Insecte.",
                "de": "Ein Item, das einem Pokémon zum Tragen gegeben werden kann. Es verstärkt Attacken vom Typ Käfer.",
            ]),
        "hard-stone": Entry(appOriginalLanguages: [],
            names: ["ko": "딱딱한돌", "en": "Hard Stone", "ja": "かたいいし", "es": "Piedra Dura", "fr": "Pierre Dure", "de": "Granitstein"],
            texts: [
                "ko": "절대 깨지지 않는 돌. 지니게 하면 바위타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a durable stone that boosts the power of Rock-type moves.",
                "ja": "ぜったいに　われない　いし。　もたせると　いわタイプの　わざの　いりょくが　あがる。",
                "es": "Debe llevarla un Pokémon. La robustez de la piedra fortalece los movimientos de tipo Roca.",
                "fr": "Objet à tenir. Une pierre incassable qui augmente la puissance des capacités de type Roche.",
                "de": "Ein Item zum Tragen. Ein unzerbrechlicher Stein, der Attacken vom Typ Gestein verstärkt.",
            ]),
        "spell-tag": Entry(appOriginalLanguages: [],
            names: ["ko": "저주의부적", "en": "Spell Tag", "ja": "のろいのおふだ", "es": "Hechizo", "fr": "Rune Sort", "de": "Bannsticker"],
            texts: [
                "ko": "괴상하고 으스스한 부적. 지니게 하면 고스트타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a sinister, eerie tag that boosts the power of Ghost-type moves.",
                "ja": "あやしくて　ぶきみな　おふだ。　もたせると　ゴーストタイプの　わざの　いりょくが　あがる。",
                "es": "Misterioso y siniestro objeto que potencia los movimientos de tipo Fantasma. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un talisman sinistre et étrange qui augmente la puissance des capacités de type Spectre.",
                "de": "Ein Item zum Tragen. Ein fieser, unheimlicher Sticker, der Attacken vom Typ Geist verstärkt.",
            ]),
        "dragon-fang": Entry(appOriginalLanguages: [],
            names: ["ko": "용의이빨", "en": "Dragon Fang", "ja": "りゅうのキバ", "es": "Colmillo de Dragón", "fr": "Croc Dragon", "de": "Drachenzahn"],
            texts: [
                "ko": "단단하고 날카로운 이빨. 지니게 하면 드래곤타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This hard and sharp fang boosts the power of Dragon-type moves.",
                "ja": "かたくて　するどい　キバ。　もたせると　ドラゴンタイプの　わざの　いりょくが　あがる。",
                "es": "Colmillo de gran dureza que refuerza los movimientos de tipo Dragón. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un croc dur et pointu qui augmente la puissance des capacités de type Dragon.",
                "de": "Ein Item zum Tragen. Ein harter und scharfer Reißzahn, der Attacken vom Typ Drache verstärkt.",
            ]),
        "black-glasses": Entry(appOriginalLanguages: [],
            names: ["ko": "검은안경", "en": "Black Glasses", "ja": "くろいメガネ", "es": "Gafas de Sol", "fr": "Lunettes Noires", "de": "Schattenbrille"],
            texts: [
                "ko": "괴상하게 보이는 안경. 지니게 하면 악타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a pair of shady-looking glasses that boost the power of Dark-type moves.",
                "ja": "あやしく　みえる　メガネ。　もたせると　あくタイプの　わざの　いりょくが　あがる。",
                "es": "Debe llevarlas un Pokémon. Fortalecen los movimientos de tipo Siniestro.",
                "fr": "Objet à tenir. Une paire de lunettes à l’aspect louche qui augmente la puissance des capacités de type Ténèbres.",
                "de": "Ein Item zum Tragen. Eine dunkle Brille, die Attacken vom Typ Unlicht verstärkt.",
            ]),
        "silk-scarf": Entry(appOriginalLanguages: [],
            names: ["ko": "실크스카프", "en": "Silk Scarf", "ja": "シルクのスカーフ", "es": "Pañuelo de Seda", "fr": "Mouchoir Soie", "de": "Seidenschal"],
            texts: [
                "ko": "감촉이 좋은 스카프. 지니게 하면 노말타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a sumptuous scarf that boosts the power of Normal-type moves.",
                "ja": "はだざわりの　よい　スカーフ。　もたせると　ノーマルタイプの　わざの　いりょくが　あがる。",
                "es": "La delicadeza del pañuelo fortalece los movimientos de tipo Normal. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un mouchoir somptueux qui augmente la puissance des capacités de type Normal.",
                "de": "Ein Item zum Tragen. Ein kostbarer Schal, der Attacken vom Typ Normal verstärkt.",
            ]),
        "fairy-feather": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "요정의깃털", "en": "Fairy Feather", "ja": "ようせいのハネ", "es": "Pluma Feérica", "fr": "Plume Enchantée", "de": "Feendaune"],
            texts: [
                "ko": "지니게 하면 페어리타입 기술의 위력이 올라가는 깃털.",
                "en": "An item to be held by a Pokémon. It is a feather that boosts the power of Fairy-type moves.",
                "ja": "もたせると　フェアリータイプの　わざの　いりょくが　あがる　ハネ。",
                "es": "Una pluma que potencia los movimientos de tipo Hada del Pokémon que la lleve.",
                "fr": "Une plume qui renforce la puissance des attaques de type Fée du Pokémon qui la tient.",
                "pt": "Uma pena que aumenta o poder dos golpes do tipo Fada do Pokémon que a segurar.",
                "de": "Eine Feder, die die Stärke von Feen-Attacken des Trägers erhöht.",
                "ru": "Перо, повышающее силу атак типа «Фея» у покемона, который его держит.",
            ]),
        "heat-rock": Entry(appOriginalLanguages: [],
            names: ["ko": "뜨거운바위", "en": "Heat Rock", "ja": "あついいわ", "es": "Roca Calor", "fr": "Roche Chaude", "de": "Heißbrocken"],
            texts: [
                "ko": "지니게 한 포켓몬이 쾌청을 쓰면 여느 때보다 쾌청의 시간이 길어진다.",
                "en": "An item to be held by a Pokémon. It extends the duration of the move Sunny Day when used by the holder.",
                "ja": "もたせた　ポケモンが　にほんばれを　つかうと　いつもより　はれの　じかんが　ながくなる。",
                "es": "Prolonga la duración del movimiento Día Soleado que use el Pokémon que la lleva.",
                "fr": "Objet à tenir. Prolonge la durée de la capacité Zénith utilisée par le porteur.",
                "de": "Ein Item zum Tragen. Verlängert die Dauer von Sonnentag, wenn der Träger diese Attacke einsetzt.",
            ]),
        "damp-rock": Entry(appOriginalLanguages: [],
            names: ["ko": "축축한바위", "en": "Damp Rock", "ja": "しめったいわ", "es": "Roca Lluvia", "fr": "Roche Humide", "de": "Nassbrocken"],
            texts: [
                "ko": "지니게 한 포켓몬이 비바라기를 쓰면 여느 때보다 비 내리는 시간이 길어진다.",
                "en": "An item to be held by a Pokémon. It extends the duration of the move Rain Dance when used by the holder.",
                "ja": "もたせた　ポケモンが　あまごいを　つかうと　いつもより　あめの　じかんが　ながくなる。",
                "es": "Prolonga la duración del movimiento Danza Lluvia que use el Pokémon que la lleva.",
                "fr": "Objet à tenir. Prolonge la durée de la capacité Danse Pluie utilisée par le porteur.",
                "de": "Ein Item zum Tragen. Verlängert die Dauer von Regentanz, wenn der Träger diese Attacke einsetzt.",
            ]),
        "smooth-rock": Entry(appOriginalLanguages: [],
            names: ["ko": "보송보송바위", "en": "Smooth Rock", "ja": "さらさらいわ", "es": "Roca Suave", "fr": "Roche Lisse", "de": "Glattbrocken"],
            texts: [
                "ko": "지니게 한 포켓몬이 모래바람을 쓰면 여느 때보다 모래바람의 시간이 길어진다.",
                "en": "An item to be held by a Pokémon. It extends the duration of the move Sandstorm when used by the holder.",
                "ja": "もたせた　ポケモンが　すなあらしを　つかうと　いつもより　すなあらしの　じかんが　ながくなる。",
                "es": "Prolonga la duración del movimiento Tormenta de Arena que use el Pokémon que la lleva.",
                "fr": "Objet à tenir. Prolonge la durée de la capacité Tempête de Sable utilisée par le porteur.",
                "de": "Ein Item zum Tragen. Verlängert die Dauer von Sandsturm, wenn der Träger diese Attacke einsetzt.",
            ]),
        "icy-rock": Entry(appOriginalLanguages: [],
            names: ["ko": "차가운바위", "en": "Icy Rock", "ja": "つめたいいわ", "es": "Roca Helada", "fr": "Roche Glace", "de": "Eisbrocken"],
            texts: [
                "ko": "지니게 한 포켓몬이 싸라기눈을 쓰면 여느 때보다 싸라기눈의 시간이 길어진다.",
                "en": "An item to be held by a Pokémon. It extends the duration of the move Hail when used by the holder.",
                "ja": "もたせた　ポケモンが　あられを　つかうと　いつもより　あられの　じかんが　ながくなる。",
                "es": "Prolonga la duración del movimiento Granizo que use el Pokémon que la lleva.",
                "fr": "Objet à tenir. Prolonge la durée de la capacité Grêle utilisée par le porteur.",
                "de": "Ein Item zum Tragen. Verlängert die Dauer von Hagelsturm, wenn der Träger diese Attacke einsetzt.",
            ]),
        "teal-mask": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "벽록의가면", "en": "Teal Mask", "ja": "みどりのめん", "es": "Máscara Turquesa", "fr": "Masque Turquoise", "de": "Türkisgrüne Maske"],
            texts: [
                "ko": "오거폰이 쓰는 벽록색 가면. 지니게 하면 모습이 풀타입 그대로 빛난다.",
                "en": "A teal mask that Ogerpon wears. When held by Ogerpon, it shines in its pure Grass-type form.",
                "ja": "オーガポンが　つける　みどりいろの　おめん。　もたせると　くさタイプの　すがたで　かがやく。",
                "es": "Una máscara turquesa que lleva Ogerpon. Si la lleva Ogerpon, brilla en su forma de tipo Planta.",
                "fr": "Un masque turquoise que porte Ogerpon. Tenu par Ogerpon, il brille sous sa forme de type Plante.",
                "pt": "Uma máscara verde-azulada usada por Ogerpon. Quando Ogerpon a segura, brilha em sua forma do tipo Planta.",
                "de": "Eine türkisfarbene Maske, die Ogerpon trägt. Hält Ogerpon sie, strahlt es in seiner reinen Pflanze-Form.",
                "ru": "Бирюзовая маска, которую носит Огерпон. Если её держит Огерпон, он сияет в форме типа «Трава».",
            ]),
        "wellspring-mask": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "우물의가면", "en": "Wellspring Mask", "ja": "いどのめん", "es": "Máscara Fuente", "fr": "Masque du Puits", "de": "Brunnenmaske"],
            texts: [
                "ko": "오거폰이 쓰는 우물색 가면. 지니게 하면 풀과 물타입의 모습으로 빛난다.",
                "en": "A mask in the colors of a wellspring that Ogerpon wears. When held by Ogerpon, it shines in a Grass- and Water-type form.",
                "ja": "オーガポンが　つける　いどいろの　おめん。　もたせると　くさと　みずタイプの　すがたで　かがやく。",
                "es": "Una máscara con los colores de un manantial que lleva Ogerpon. Si la lleva Ogerpon, brilla en una forma de tipo Planta y Agua.",
                "fr": "Un masque aux couleurs d'une source que porte Ogerpon. Tenu par Ogerpon, il brille sous une forme de type Plante et Eau.",
                "pt": "Uma máscara nas cores de uma nascente usada por Ogerpon. Quando Ogerpon a segura, brilha em uma forma dos tipos Planta e Água.",
                "de": "Eine Maske in den Farben einer Quelle, die Ogerpon trägt. Hält Ogerpon sie, strahlt es in einer Pflanze-Wasser-Form.",
                "ru": "Маска цветов родника, которую носит Огерпон. Если её держит Огерпон, он сияет в форме типов «Трава» и «Вода».",
            ]),
        "hearthflame-mask": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "화덕의가면", "en": "Hearthflame Mask", "ja": "かまどのめん", "es": "Máscara Horno", "fr": "Masque du Fourneau", "de": "Ofenmaske"],
            texts: [
                "ko": "오거폰이 쓰는 화덕색 가면. 지니게 하면 풀과 불꽃타입의 모습으로 빛난다.",
                "en": "A mask in the colors of a hearth fire that Ogerpon wears. When held by Ogerpon, it shines in a Grass- and Fire-type form.",
                "ja": "オーガポンが　つける　かまどいろの　おめん。　もたせると　くさと　ほのおタイプの　すがたで　かがやく。",
                "es": "Una máscara con los colores de un hogar encendido que lleva Ogerpon. Si la lleva Ogerpon, brilla en una forma de tipo Planta y Fuego.",
                "fr": "Un masque aux couleurs d'un foyer que porte Ogerpon. Tenu par Ogerpon, il brille sous une forme de type Plante et Feu.",
                "pt": "Uma máscara nas cores de uma lareira usada por Ogerpon. Quando Ogerpon a segura, brilha em uma forma dos tipos Planta e Fogo.",
                "de": "Eine Maske in den Farben eines Herdfeuers, die Ogerpon trägt. Hält Ogerpon sie, strahlt es in einer Pflanze-Feuer-Form.",
                "ru": "Маска цветов очага, которую носит Огерпон. Если её держит Огерпон, он сияет в форме типов «Трава» и «Огонь».",
            ]),
        "cornerstone-mask": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "주춧돌의가면", "en": "Cornerstone Mask", "ja": "いしずえのめん", "es": "Máscara Cimiento", "fr": "Masque de la Pierre", "de": "Fundamentmaske"],
            texts: [
                "ko": "오거폰이 쓰는 주춧돌색 가면. 지니게 하면 풀과 바위타입의 모습으로 빛난다.",
                "en": "A mask in the colors of a cornerstone that Ogerpon wears. When held by Ogerpon, it shines in a Grass- and Rock-type form.",
                "ja": "オーガポンが　つける　いしずえいろの　おめん。　もたせると　くさと　いわタイプの　すがたで　かがやく。",
                "es": "Una máscara con los colores de una piedra angular que lleva Ogerpon. Si la lleva Ogerpon, brilla en una forma de tipo Planta y Roca.",
                "fr": "Un masque aux couleurs d'une pierre angulaire que porte Ogerpon. Tenu par Ogerpon, il brille sous une forme de type Plante et Roche.",
                "pt": "Uma máscara nas cores de uma pedra angular usada por Ogerpon. Quando Ogerpon a segura, brilha em uma forma dos tipos Planta e Pedra.",
                "de": "Eine Maske in den Farben eines Grundsteins, die Ogerpon trägt. Hält Ogerpon sie, strahlt es in einer Pflanze-Gestein-Form.",
                "ru": "Маска цветов краеугольного камня, которую носит Огерпон. Если её держит Огерпон, он сияет в форме типов «Трава» и «Камень».",
            ]),
        "linking-cord": Entry(appOriginalLanguages: ["ko", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "연결의끈", "en": "Linking Cord", "ja": "つながりのヒモ", "es": "Cordón Unión", "fr": "Fil de Liaison", "de": "Verbindungsschnur"],
            texts: [
                "ko": "신비한 끈. 사용하면 통신 교환으로 진화하는 포켓몬이 그 자리에서 진화한다.",
                "ja": "ふしぎな　ヒモ。　つかうと　つうしんこうかんで　しんかする　ポケモンが　その　ばで　しんかする。",
                "es": "Un cordón misterioso. Al usarlo, un Pokémon que evoluciona por intercambio evoluciona al instante.",
                "fr": "Un fil mystérieux. Utilisé, il fait évoluer aussitôt un Pokémon qui évolue par échange.",
                "pt": "Um cordão misterioso. Ao usá-lo, um Pokémon que evolui por troca evolui na hora.",
                "de": "Eine geheimnisvolle Schnur. Verwendet entwickelt sie ein Pokémon sofort, das sich durch Tausch entwickelt.",
                "ru": "Таинственный шнур. Если его применить, покемон, эволюционирующий обменом, эволюционирует сразу.",
                "en": "A string exuding a mysterious energy that makes you feel a strange sense of connection. It’s loved by certain Pokémon.",
            ]),
        "tart-apple": Entry(appOriginalLanguages: [],
            names: ["ko": "새콤한사과", "en": "Tart Apple", "ja": "すっぱいりんご", "es": "Manzana Ácida", "fr": "Pomme Acidulée", "de": "Saurer Apfel"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 사과. 엄청나게 새콤하다.",
                "en": "A peculiar apple that can make a certain species of Pokémon evolve. It’s exceptionally tart.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　りんご。　とにかく　すっぱい。",
                "es": "Curiosa manzana, de sabor particularmente ácido, que hace evolucionar a determinadas especies de Pokémon.",
                "fr": "Une pomme mystérieuse très acide qui permet de faire évoluer un certain Pokémon.",
                "de": "Dieser sonderbare Apfel löst bei einem bestimmten Pokémon die Entwicklung aus. Er schmeckt sehr sauer.",
            ]),
        "sweet-apple": Entry(appOriginalLanguages: [],
            names: ["ko": "달콤한사과", "en": "Sweet Apple", "ja": "あまーいりんご", "es": "Manzana Dulce", "fr": "Pomme Sucrée", "de": "Süßer Apfel"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 사과. 엄청나게 달다.",
                "en": "A peculiar apple that can make a certain species of Pokémon evolve. It’s exceptionally sweet.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　りんご。　とにかく　あまい。",
                "es": "Curiosa manzana, de sabor particularmente dulce, que hace evolucionar a determinadas especies de Pokémon.",
                "fr": "Une pomme mystérieuse très sucrée qui permet de faire évoluer un certain Pokémon.",
                "de": "Dieser sonderbare Apfel löst bei einem bestimmten Pokémon die Entwicklung aus. Er schmeckt sehr süß.",
            ]),
        "syrupy-apple": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "꿀맛사과", "en": "Syrupy Apple", "ja": "みついりりんご", "es": "Manzana Melosa", "fr": "Pomme Nectar", "de": "Saftiger Apfel"],
            texts: [
                "ko": "시럽이 가득 배어든 사과. 어떤 포켓몬에게 주면 진화한다.",
                "en": "A very syrupy apple. A certain Pokémon evolves when it is given this apple.",
                "ja": "シロップが　たっぷり　しみこんだ　リンゴ。あるポケモンに　あたえると　しんかする。",
                "es": "Una manzana empapada de sirope. Cierto Pokémon evoluciona si se le da esta manzana.",
                "fr": "Une pomme gorgée de sirop. Un certain Pokémon évolue si on la lui donne.",
                "pt": "Uma maçã encharcada de xarope. Certo Pokémon evolui ao receber esta maçã.",
                "de": "Ein Apfel, der vor Sirup trieft. Ein bestimmtes Pokémon entwickelt sich, wenn es ihn bekommt.",
                "ru": "Яблоко, пропитанное сиропом. Некоторый покемон эволюционирует, если ему его дать.",
            ]),
        "cracked-pot": Entry(appOriginalLanguages: [],
            names: ["ko": "깨진포트", "en": "Cracked Pot", "ja": "われたポット", "es": "Tetera Agrietada", "fr": "Théière Fêlée", "de": "Rissige Kanne"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 포트. 깨졌지만 차는 맛있어진다.",
                "en": "A peculiar teapot that can make a certain species of Pokémon evolve. It may be cracked, but tea poured from it is delicious.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　ポット。　われているが　おちゃは　おいしくなる。",
                "es": "Curiosa tetera que hace evolucionar a determinadas especies de Pokémon. Pese a estar agrietada, sirve un té exquisito.",
                "fr": "Un récipient mystérieux pouvant faire évoluer un certain Pokémon. Il est abîmé, mais on y fait du bon thé.",
                "de": "Diese spezielle Kanne löst bei einem bestimmten Pokémon die Entwicklung aus. Sie weist zwar Risse auf, aber das wirkt sich nicht negativ auf den Tee aus.",
            ]),
        "chipped-pot": Entry(appOriginalLanguages: [],
            names: ["ko": "이빠진포트", "en": "Chipped Pot", "ja": "かけたポット", "es": "Tetera Rota", "fr": "Théière Ébréchée", "de": "Löchrige Kanne"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 포트. 이가 빠졌지만 차는 맛있어진다.",
                "en": "A peculiar teapot that can make a certain species of Pokémon evolve. It may be chipped, but tea poured from it is delicious.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　ポット。　かけているが　おちゃは　おいしくなる。",
                "es": "Curiosa tetera que hace evolucionar a determinadas especies de Pokémon. Pese a estar rota, sirve un té exquisito.",
                "fr": "Un récipient mystérieux pouvant faire évoluer un certain Pokémon. Il est ébréché, mais on y fait du bon thé.",
                "de": "Diese spezielle Kanne löst bei einem bestimmten Pokémon die Entwicklung aus. Sie weist zwar Löcher auf, aber das wirkt sich nicht negativ auf den Tee aus.",
            ]),
        "auspicious-armor": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "축복받은갑옷", "en": "Auspicious Armor", "ja": "イワイノヨロイ", "es": "Armadura Auspiciosa", "fr": "Armure de la Fortune", "de": "Glorienrüstung"],
            texts: [
                "ko": "상서로운 기운이 감도는 갑옷. 어떤 포켓몬에게 주면 진화한다.",
                "en": "Armor brimming with an auspicious aura. A certain Pokémon evolves when it is given this armor.",
                "ja": "めでたい　オーラが　ただよう　よろい。あるポケモンに　あたえると　しんかする。",
                "es": "Una armadura que rebosa un aura de buen augurio. Cierto Pokémon evoluciona si se le da esta armadura.",
                "fr": "Une armure qui déborde d'une aura de bon augure. Un certain Pokémon évolue si on la lui donne.",
                "pt": "Uma armadura repleta de uma aura auspiciosa. Certo Pokémon evolui ao receber esta armadura.",
                "de": "Eine Rüstung voller glückverheißender Aura. Ein bestimmtes Pokémon entwickelt sich, wenn es sie bekommt.",
                "ru": "Доспехи, наполненные благоприятной аурой. Некоторый покемон эволюционирует, если ему их дать.",
            ]),
        "malicious-armor": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "저주받은갑옷", "en": "Malicious Armor", "ja": "ノロイノヨロイ", "es": "Armadura Maldita", "fr": "Armure de la Rancune", "de": "Fluchrüstung"],
            texts: [
                "ko": "악의가 감도는 갑옷. 어떤 포켓몬에게 주면 진화한다.",
                "en": "Armor brimming with a malicious aura. A certain Pokémon evolves when it is given this armor.",
                "ja": "あくいが　ただよう　よろい。あるポケモンに　あたえると　しんかする。",
                "es": "Una armadura que rebosa un aura maliciosa. Cierto Pokémon evoluciona si se le da esta armadura.",
                "fr": "Une armure qui déborde d'une aura malveillante. Un certain Pokémon évolue si on la lui donne.",
                "pt": "Uma armadura repleta de uma aura maliciosa. Certo Pokémon evolui ao receber esta armadura.",
                "de": "Eine Rüstung voller böser Aura. Ein bestimmtes Pokémon entwickelt sich, wenn es sie bekommt.",
                "ru": "Доспехи, наполненные злой аурой. Некоторый покемон эволюционирует, если ему их дать.",
            ]),
        "galarica-cuff": Entry(appOriginalLanguages: [],
            names: ["ko": "가라두구팔찌", "en": "Galarica Cuff", "ja": "ガラナツブレス", "es": "Brazal Galanuez", "fr": "Bracelet Galanoa", "de": "Galarnuss-Reif"],
            texts: [
                "ko": "가라두구가지를 엮어서 만든 팔찌. 가라르지방의 야돈에게 채워주면 기뻐한다.",
                "en": "A cuff made from woven-together Galarica Twigs. Giving it to Galarian Slowpoke makes the Pokémon very happy.",
                "ja": "ガラナツのえだを　あみこんだ　ブレスレット。　ガラルちほうの　ヤドンに　つけてあげると　よろこぶ。",
                "es": "Un brazalete hecho de Ramas de Galanuez trenzadas. Los Slowpoke de Galar se ponen contentísimos si lo reciben como regalo.",
                "fr": "Un bracelet confectionné à partir de Branches Galanoa. Les Ramoloss de Galar adorent en porter.",
                "de": "Ein Armreif, der aus Galarnuss-Zweigen gewoben wird. Galar-Flegmon freuen sich, wenn sie diesen anlegen dürfen.",
            ]),
        "galarica-wreath": Entry(appOriginalLanguages: [],
            names: ["ko": "가라두구머리장식", "en": "Galarica Wreath", "ja": "ガラナツリース", "es": "Corona Galanuez", "fr": "Couronne Galanoa", "de": "Galarnuss-Kranz"],
            texts: [
                "ko": "가라두구가지를 엮어서 만든 머리 장식. 가라르지방의 야돈에게 씌워주면 기뻐한다.",
                "en": "A wreath made from woven-together Galarica Twigs. Placing it on the head of a Galarian Slowpoke makes the Pokémon very happy.",
                "ja": "ガラナツのえだを　あみこんだ　かんむり。　ガラルちほうの　ヤドンに　かぶせてあげると　よろこぶ。",
                "es": "Una corona hecha de Ramas de Galanuez trenzadas. Los Slowpoke de Galar se ponen contentísimos cuando la llevan puesta.",
                "fr": "Une couronne confectionnée à partir de Branches Galanoa. Les Ramoloss de Galar adorent en porter.",
                "de": "Ein Kranz, der aus Galarnuss-Zweigen gewoben wurde. Galar-Flegmon freuen sich, wenn sie diesen tragen dürfen.",
            ]),
        "unremarkable-teacup": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "범작찻잔", "en": "Unremarkable Teacup", "ja": "ボンサクのちゃわん", "es": "Cuenco Mediocre", "fr": "Bol Médiocre", "de": "Simple Teeschale"],
            texts: [
                "ko": "별다를 것 없는 평범한 찻잔. 어떤 포켓몬이 깃들면 진화한다.",
                "en": "An unremarkable, ordinary-looking teacup. A certain Pokémon evolves when it takes up residence in it.",
                "ja": "とくに　かわったところの　ない　ふつうの　ちゃわん。あるポケモンが　やどると　しんかする。",
                "es": "Una taza de té corriente y sin nada especial. Cierto Pokémon evoluciona si se instala en ella.",
                "fr": "Une tasse à thé ordinaire, sans rien de remarquable. Un certain Pokémon évolue s'il s'y installe.",
                "pt": "Uma xícara de chá comum, sem nada de especial. Certo Pokémon evolui ao se instalar nela.",
                "de": "Eine gewöhnliche, unscheinbare Teetasse. Ein bestimmtes Pokémon entwickelt sich, wenn es sich darin einnistet.",
                "ru": "Обычная, ничем не примечательная чайная чашка. Некоторый покемон эволюционирует, если поселится в ней.",
            ]),
        "masterpiece-teacup": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "걸작찻잔", "en": "Masterpiece Teacup", "ja": "ケッサクのちゃわん", "es": "Cuenco Exquisito", "fr": "Bol Exceptionnel", "de": "Edle Teeschale"],
            texts: [
                "ko": "정교하게 만들어진 걸작 찻잔. 어떤 포켓몬이 깃들면 진화한다.",
                "en": "A masterpiece of a teacup, exquisitely made. A certain Pokémon evolves when it takes up residence in it.",
                "ja": "せいこうに　つくられた　けっさくの　ちゃわん。あるポケモンが　やどると　しんかする。",
                "es": "Una taza de té que es una obra maestra, de factura exquisita. Cierto Pokémon evoluciona si se instala en ella.",
                "fr": "Une tasse à thé qui est un chef-d'œuvre, d'une facture exquise. Un certain Pokémon évolue s'il s'y installe.",
                "pt": "Uma xícara de chá que é uma obra-prima, feita com requinte. Certo Pokémon evolui ao se instalar nela.",
                "de": "Eine meisterhaft gefertigte Teetasse. Ein bestimmtes Pokémon entwickelt sich, wenn es sich darin einnistet.",
                "ru": "Чайная чашка-шедевр, изысканной работы. Некоторый покемон эволюционирует, если поселится в ней.",
            ]),
        "metal-alloy": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "복합금속", "en": "Metal Alloy", "ja": "ふくごうきんぞく", "es": "Metal Compuesto", "fr": "Métal Composite", "de": "Legierungsmetall"],
            texts: [
                "ko": "신기한 금속 합금. 어떤 포켓몬이 이 합금에 닿으면 진화한다.",
                "en": "A peculiar metal alloy. A certain Pokémon evolves when it is exposed to this alloy.",
                "ja": "ふしぎな　きんぞくの　ごうきん。あるポケモンが　ふれると　しんかする。",
                "es": "Una extraña aleación de metales. Cierto Pokémon evoluciona si se expone a esta aleación.",
                "fr": "Un étrange alliage métallique. Un certain Pokémon évolue s'il y est exposé.",
                "pt": "Uma estranha liga metálica. Certo Pokémon evolui ao ser exposto a esta liga.",
                "de": "Eine seltsame Metalllegierung. Ein bestimmtes Pokémon entwickelt sich, wenn es ihr ausgesetzt wird.",
                "ru": "Необычный металлический сплав. Некоторый покемон эволюционирует, если подвергнется его воздействию.",
            ]),
        "peat-block": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "피트블록", "en": "Peat Block", "ja": "ピートブロック", "es": "Bloque de Turba", "fr": "Bloc de Tourbe", "de": "Torfblock"],
            texts: [
                "ko": "신비한 에너지가 가득한 이탄 덩어리. 어떤 포켓몬이 이 덩어리에 닿으면 진화한다.",
                "en": "A block of peat brimming with mysterious energy. A certain Pokémon evolves when it is exposed to this block.",
                "ja": "ふしぎな　エネルギーに　みちた　でいたんの　かたまり。あるポケモンが　ふれると　しんかする。",
                "es": "Un bloque de turba lleno de energía misteriosa. Cierto Pokémon evoluciona si se expone a este bloque.",
                "fr": "Un bloc de tourbe plein d'énergie mystérieuse. Un certain Pokémon évolue s'il y est exposé.",
                "pt": "Um bloco de turfa repleto de energia misteriosa. Certo Pokémon evolui ao ser exposto a este bloco.",
                "de": "Ein Torfblock voll geheimnisvoller Energie. Ein bestimmtes Pokémon entwickelt sich, wenn es ihm ausgesetzt wird.",
                "ru": "Брикет торфа, полный таинственной энергии. Некоторый покемон эволюционирует, если подвергнется его воздействию.",
            ]),
        "black-augurite": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "검은휘석", "en": "Black Augurite", "ja": "くろのきせき", "es": "Mineral Negro", "fr": "Obsidienne", "de": "Schwarzaugit"],
            texts: [
                "ko": "검게 빛나는 신기한 광물. 어떤 포켓몬이 이 광물에 닿으면 진화한다.",
                "en": "A peculiar black mineral that gleams. A certain Pokémon evolves when it is exposed to this mineral.",
                "ja": "くろく　かがやく　ふしぎな　こうぶつ。あるポケモンが　ふれると　しんかする。",
                "es": "Un extraño mineral negro y brillante. Cierto Pokémon evoluciona si se expone a este mineral.",
                "fr": "Un étrange minéral noir et brillant. Un certain Pokémon évolue s'il y est exposé.",
                "pt": "Um estranho mineral preto e reluzente. Certo Pokémon evolui ao ser exposto a este mineral.",
                "de": "Ein seltsames, schwarz glänzendes Mineral. Ein bestimmtes Pokémon entwickelt sich, wenn es ihm ausgesetzt wird.",
                "ru": "Необычный блестящий чёрный минерал. Некоторый покемон эволюционирует, если подвергнется его воздействию.",
            ]),
        "scroll-of-darkness": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "악의 족자", "en": "Scroll of Darkness", "ja": "あくのかけじく", "es": "Manuscrito Sombras", "fr": "Rouleau des Ténèbres", "de": "Unlicht-Schriftrolle"],
            texts: [
                "ko": "악의 탑의 가르침이 적힌 두루마리. 어떤 포켓몬이 읽으면 진화한다.",
                "en": "A scroll that records the teachings of the Tower of Darkness. A certain Pokémon evolves when it studies it.",
                "ja": "あくのとうの　おしえが　かかれた　まきもの。あるポケモンが　よむと　しんかする。",
                "es": "Un pergamino con las enseñanzas de la Torre Oscura. Cierto Pokémon evoluciona si lo estudia.",
                "fr": "Un parchemin consignant les enseignements de la Tour Obscure. Un certain Pokémon évolue s'il l'étudie.",
                "pt": "Um pergaminho com os ensinamentos da Torre da Escuridão. Certo Pokémon evolui ao estudá-lo.",
                "de": "Eine Schriftrolle mit den Lehren des Turms der Finsternis. Ein bestimmtes Pokémon entwickelt sich, wenn es sie studiert.",
                "ru": "Свиток с учением Башни Тьмы. Некоторый покемон эволюционирует, если изучит его.",
            ]),
        "scroll-of-waters": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "물의 족자", "en": "Scroll of Waters", "ja": "みずのかけじく", "es": "Manuscrito Aguas", "fr": "Rouleau de l'Eau", "de": "Wasser-Schriftrolle"],
            texts: [
                "ko": "물의 탑의 가르침이 적힌 두루마리. 어떤 포켓몬이 읽으면 진화한다.",
                "en": "A scroll that records the teachings of the Tower of Waters. A certain Pokémon evolves when it studies it.",
                "ja": "みずのとうの　おしえが　かかれた　まきもの。あるポケモンが　よむと　しんかする。",
                "es": "Un pergamino con las enseñanzas de la Torre Agua. Cierto Pokémon evoluciona si lo estudia.",
                "fr": "Un parchemin consignant les enseignements de la Tour d'Eau. Un certain Pokémon évolue s'il l'étudie.",
                "pt": "Um pergaminho com os ensinamentos da Torre da Água. Certo Pokémon evolui ao estudá-lo.",
                "de": "Eine Schriftrolle mit den Lehren des Wasserturms. Ein bestimmtes Pokémon entwickelt sich, wenn es sie studiert.",
                "ru": "Свиток с учением Башни Воды. Некоторый покемон эволюционирует, если изучит его.",
            ]),
        "oval-stone": Entry(appOriginalLanguages: [],
            names: ["ko": "동글동글돌", "en": "Oval Stone", "ja": "まんまるいし", "es": "Piedra Oval", "fr": "Pierre Ovale", "de": "Ovaler Stein"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 돌. 구슬처럼 둥글다.",
                "en": "A peculiar stone that can make certain species of Pokémon evolve. It’s as round as a Pokémon Egg.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　いし。　たまのように　まるい。",
                "es": "Una piedra peculiar que hace evolucionar a algunos Pokémon. Tiene forma de huevo.",
                "fr": "Une pierre étrange qui fait évoluer certaines espèces de Pokémon. Elle a la forme d’un œuf.",
                "de": "Dieser besondere, eiförmige Stein hilft manchen Pokémon bei ihrer Entwicklung.",
            ]),
        "razor-claw": Entry(appOriginalLanguages: [],
            names: ["ko": "예리한손톱", "en": "Razor Claw", "ja": "するどいツメ", "es": "Garra Afilada", "fr": "Griffe Rasoir", "de": "Scharfklaue"],
            texts: [
                "ko": "날카롭고 뾰족한 손톱. 지니게 하면 기술이 급소에 맞기 쉬워진다.",
                "en": "An item to be held by a Pokémon. This sharply hooked claw increases the holder’s critical-hit ratio.",
                "ja": "するどく　とがった　ツメ。　もたせると　わざが　きゅうしょに　あたりやすくなる。",
                "es": "Aumenta la probabilidad de que el Pokémon que la lleve consiga un golpe crítico.",
                "fr": "Objet à tenir. Une griffe crochue et pointue augmentant le taux de critiques.",
                "de": "Ein Item zum Tragen. Die scharfe Klaue erhöht die Volltrefferquote des Trägers.",
            ]),
        "razor-fang": Entry(appOriginalLanguages: [],
            names: ["ko": "예리한이빨", "en": "Razor Fang", "ja": "するどいキバ", "es": "Colmillo Agudo", "fr": "Croc Rasoir", "de": "Scharfzahn"],
            texts: [
                "ko": "날카롭고 뾰족한 이빨. 지니게 하면 데미지를 줬을 때 풀죽게 하기도 한다.",
                "en": "An item to be held by a Pokémon. When the holder successfully inflicts damage, the target may also flinch.",
                "ja": "するどく　とがった　キバ。　もたせると　ダメージを　あたえたとき　ひるませることが　ある。",
                "es": "Si lo lleva un Pokémon, puede amedrentar al objetivo al infligirle daño.",
                "fr": "Objet à tenir. Peut apeurer l’ennemi quand le porteur lui inflige des dégâts.",
                "de": "Ein Item zum Tragen. Verursacht der Träger Schaden, schreckt das Ziel eventuell zurück.",
            ]),
        "strawberry-sweet": Entry(appOriginalLanguages: [],
            names: ["ko": "딸기사탕공예", "en": "Strawberry Sweet", "ja": "いちごアメざいく", "es": "Confite Fresa", "fr": "Fraise en Sucre", "de": "Zucker-Erdbeere"],
            texts: [
                "ko": "딸기 모양의 사탕공예. 마빌크에게 지니게 하면 빙빙 돌며 기뻐한다.",
                "en": "A strawberry-shaped sweet. When a Milcery holds this, it will spin around happily.",
                "ja": "いちごの　かたちを　した　アメざいく。　マホミルに　もたせてあげると　くるくる　まわって　よろこぶ。",
                "es": "Figura de caramelo con forma de fresa. Al dárselo a Milcery, se pone a girar rebosante de alegría.",
                "fr": "Un bonbon en forme de fraise. Quand on le donne à un Crèmy, il danse de bonheur.",
                "de": "Zuckerwerk in Form einer Erdbeere. Gibt man es Hokumil zum Tragen, dreht es sich vor Freude im Kreis.",
            ]),
        "metal-coat": Entry(appOriginalLanguages: [],
            names: ["ko": "금속코트", "en": "Metal Coat", "ja": "メタルコート", "es": "Revest. Metálico", "fr": "Peau Métal", "de": "Metallmantel"],
            texts: [
                "ko": "특수한 금속 장막. 지니게 하면 강철타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a special metallic film that can boost the power of Steel-type moves.",
                "ja": "とくしゅな　きんぞくの　まく。　もたせると　はがねタイプの　わざの　いりょくが　あがる。",
                "es": "Película metálica que fortalece los ataques de tipo Acero. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Une pellicule métallique spéciale qui augmente la puissance des capacités de type Acier.",
                "de": "Ein Item, das einem Pokémon zum Tragen gegeben werden kann. Es verstärkt Attacken vom Typ Stahl.",
            ]),
        "kings-rock": Entry(appOriginalLanguages: [],
            names: ["ko": "왕의징표석", "en": "King’s Rock", "ja": "おうじゃのしるし", "es": "Roca del Rey", "fr": "Roche Royale", "de": "King-Stein"],
            texts: [
                "ko": "지니게 하면 공격해서 데미지를 줄 때 상대를 풀죽이기도 한다.",
                "en": "An item to be held by a Pokémon. When the holder successfully inflicts damage, the target may also flinch.",
                "ja": "もたせると　こうげきして　ダメージを　あたえたときに　あいてを　ひるませることが　ある。",
                "es": "El Pokémon que la lleva puede amedrentar al Pokémon al que le inflige daño.",
                "fr": "Objet à tenir. Peut apeurer l’ennemi lorsque le porteur lui inflige des dégâts.",
                "de": "Gibst du es einem Pokémon zum Tragen, lässt es mit seinem Angriff das Ziel gelegentlich zurückschrecken.",
            ]),
        "dragon-scale": Entry(appOriginalLanguages: [],
            names: ["ko": "용의비늘", "en": "Dragon Scale", "ja": "りゅうのウロコ", "es": "Escama Dragón", "fr": "Écaille Draco", "de": "Drachenschuppe"],
            texts: [
                "ko": "단단하고 튼튼한 비늘. 드래곤타입의 포켓몬이 지니고 있는 경우가 있다.",
                "en": "A very tough and inflexible scale. Dragon-type Pokémon may be holding this item when caught.",
                "ja": "かたくて　じょうぶな　ウロコ。　ドラゴンタイプの　ポケモンが　もっていることが　ある。",
                "es": "Una gruesa y resistente escama que pueden llevar los Pokémon de tipo Dragón cuando son capturados.",
                "fr": "Une écaille épaisse et dure, parfois tenue par les Pokémon de type Dragon quand ils sont attrapés.",
                "de": "Eine dicke und starke Haut. Drachen-Pokémon tragen dieses Item gern bei sich.",
            ]),
        "up-grade": Entry(appOriginalLanguages: [],
            names: ["ko": "업그레이드", "en": "Upgrade", "ja": "アップグレード", "es": "Mejora", "fr": "Améliorator", "de": "Upgrade"],
            texts: [
                "ko": "안에 여러 가지 정보가 가득한 투명한 기계다. 실프주식회사 제품.",
                "en": "A transparent device somehow filled with all sorts of data. It was produced by Silph Co.",
                "ja": "なかに　いろんな　じょうほうが　つまった　とうめいな　きかい。　シルフ　カンパニーせい。",
                "es": "Peculiar dispositivo fabricado en Silph S. A. que contiene todo tipo de datos.",
                "fr": "Un dispositif transparent rempli de données diverses et variées. Fabriqué par la Sylphe SARL.",
                "de": "Ein durchsichtiges Gerät. Es enthält alle möglichen Daten. Hergestellt von der Silph Company.",
            ]),
        "dubious-disc": Entry(appOriginalLanguages: [],
            names: ["ko": "괴상한패치", "en": "Dubious Disc", "ja": "あやしいパッチ", "es": "Disco Extraño", "fr": "CD Douteux", "de": "Dubiosdisc"],
            texts: [
                "ko": "안에 괴상한 정보가 가득한 투명한 기계다. 제작자 불명.",
                "en": "A transparent device overflowing with dubious data. Its producer is unknown.",
                "ja": "なかに　あやしい　じょうほうが　つまった　とうめいな　きかい。　せいさくしゃは　ふめい。",
                "es": "Dispositivo transparente que contiene datos misteriosos. Es de fabricante desconocido.",
                "fr": "Un appareil transparent rempli de données douteuses. Son fabricant n’est pas connu.",
                "de": "Eine Scheibe mit seltsamen Daten. Ihr Ursprung ist unbekannt.",
            ]),
        "electirizer": Entry(appOriginalLanguages: [],
            names: ["ko": "에레키부스터", "en": "Electirizer", "ja": "エレキブースター", "es": "Electrizador", "fr": "Électriseur", "de": "Stromisierer"],
            texts: [
                "ko": "엄청난 전기의 에너지가 비축되어 있는 상자. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A box packed with a tremendous amount of electric energy. It’s loved by a certain Pokémon.",
                "ja": "とてつもない　でんきの　エネルギーが　たくわえられている　はこ。　ある　ポケモンが　このんでいる。",
                "es": "Este dispositivo contiene una gran cantidad de energía eléctrica. Cierto Pokémon lo adora.",
                "fr": "Une boîte remplie d’une énorme quantité d’énergie électrique. Appréciée d’un certain Pokémon.",
                "de": "Eine Schachtel mit elektrischer Energie. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "magmarizer": Entry(appOriginalLanguages: [],
            names: ["ko": "마그마부스터", "en": "Magmarizer", "ja": "マグマブースター", "es": "Magmatizador", "fr": "Magmariseur", "de": "Magmaisierer"],
            texts: [
                "ko": "엄청난 마그마의 에너지가 비축되어 있는 상자. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A box packed with a tremendous amount of magma energy. It’s loved by a certain Pokémon.",
                "ja": "とてつもない　マグマの　エネルギーが　たくわえられている　はこ。　ある　ポケモンが　このんでいる。",
                "es": "Esta caja contiene una enorme cantidad de energía magmática. Cierto Pokémon la adora.",
                "fr": "Une boîte remplie d’une énorme quantité d’énergie magmatique. Appréciée d’un certain Pokémon.",
                "de": "Eine Schachtel mit Magma-Energie. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "protector": Entry(appOriginalLanguages: [],
            names: ["ko": "프로텍터", "en": "Protector", "ja": "プロテクター", "es": "Protector", "fr": "Protecteur", "de": "Schützer"],
            texts: [
                "ko": "무언가의 프로텍터. 매우 단단하고 무겁다. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A protective item of some sort. It is extremely stiff and heavy. It’s loved by a certain Pokémon.",
                "ja": "なにかの　プロテクター。　とても　かたくて　おもい。　ある　ポケモンが　このんでいる。",
                "es": "Dispositivo de protección muy pesado. Cierto Pokémon lo adora.",
                "fr": "Un objet protecteur très dur et très lourd, apprécié d’un certain Pokémon.",
                "de": "Ein schützendes Item. Steif und schwer. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "reaper-cloth": Entry(appOriginalLanguages: [],
            names: ["ko": "영계의천", "en": "Reaper Cloth", "ja": "れいかいのぬの", "es": "Tela Terrible", "fr": "Tissu Fauche", "de": "Düsterumhang"],
            texts: [
                "ko": "무섭고 강한 영력이 담겨 있는 천. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A cloth imbued with horrifyingly strong spiritual energy. It’s loved by a certain Pokémon.",
                "ja": "おそろしく　つよい　れいりょくが　こめられている　ぬの。　ある　ポケモンが　このんでいる。",
                "es": "Tela imbuida de una energía espiritual muy potente. Cierto Pokémon la adora.",
                "fr": "Un tissu imprégné d’une énergie spirituelle horriblement puissante. Apprécié d’un certain Pokémon.",
                "de": "Ein Stoffumhang mit geistiger Energie. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "deep-sea-tooth": Entry(appOriginalLanguages: [],
            names: ["ko": "심해의이빨", "en": "Deep Sea Tooth", "ja": "しんかいのキバ", "es": "Diente Marino", "fr": "Dent Océan", "de": "Abysszahn"],
            texts: [
                "ko": "진주몽에게 지니게 하면 특수공격이 올라가는 이빨. 날카로운 은색으로 빛난다.",
                "en": "An item to be held by Clamperl. This fang gleams a sharp silver and raises the holder’s Sp. Atk stat.",
                "ja": "パールルに　もたせると　とくこうが　あがる　キバ。　するどく　ぎんいろに　ひかる。",
                "es": "Tiene el brillo afilado de la plata y debe llevarlo Clamperl. Sube el Ataque Especial.",
                "fr": "Objet à faire tenir à Coquiperl. Une dent de couleur argent qui augmente son Attaque Spéciale.",
                "de": "Ein Item, das von Perlu getragen werden kann. Es schimmert silbern und hebt den Spezial-Angriff.",
            ]),
        "deep-sea-scale": Entry(appOriginalLanguages: [],
            names: ["ko": "심해의비늘", "en": "Deep Sea Scale", "ja": "しんかいのウロコ", "es": "Escama Marina", "fr": "Écaille Océan", "de": "Abyssschuppe"],
            texts: [
                "ko": "진주몽에게 지니게 하면 특수방어가 올라가는 비늘. 연한 분홍색으로 빛난다.",
                "en": "An item to be held by Clamperl. This scale shines with a faint pink and raises the holder’s Sp. Def stat.",
                "ja": "パールルに　もたせると　とくぼうが　あがる　ウロコ。　うすい　ピンクいろに　ひかる。",
                "es": "Tiene un débil brillo rosado y debe llevarla Clamperl. Sube la Defensa Especial.",
                "fr": "Objet à faire tenir à Coquiperl. Une écaille de couleur rose qui augmente sa Défense Spéciale.",
                "de": "Ein Item, das von Perlu getragen werden kann. Es schimmert pink und hebt die Spezial-Verteidigung.",
            ]),
        "sachet": Entry(appOriginalLanguages: [],
            names: ["ko": "향기주머니", "en": "Sachet", "ja": "においぶくろ", "es": "Saquito Fragante", "fr": "Sachet Senteur", "de": "Duftbeutel"],
            texts: [
                "ko": "살짝 강렬한 향기가 나는 향료를 채운 주머니. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A sachet filled with fragrant perfumes that are just slightly too overwhelming. Yet it’s loved by a certain Pokémon.",
                "ja": "ちょっと　きつめの　かおりをだす　こうりょうを　つめた　ふくろ。　ある　ポケモンが　このんでいる。",
                "es": "Un saquito lleno de sustancias aromáticas cuyo perfume resulta abrumador, pero que a cierto Pokémon le encanta.",
                "fr": "Un sachet d’herbes et d’épices, au parfum trop marqué pour beaucoup, mais néanmoins apprécié d’un certain Pokémon.",
                "de": "Ein mit Parfüm gefüllter Beutel, der einen penetranten Duft verströmt und bei einer bestimmten Pokémon-Art sehr beliebt ist.",
            ]),
        "whipped-dream": Entry(appOriginalLanguages: [],
            names: ["ko": "휘핑팝", "en": "Whipped Dream", "ja": "ホイップポップ", "es": "Dulce de Nata", "fr": "Chantibonbon", "de": "Sahnehäubchen"],
            texts: [
                "ko": "풍성하게 거품을 낸 살짝 달콤한 크림. 어떤 포켓몬이 좋아한다.",
                "en": "A soft and sweet treat made of fluffy, puffy, whipped, and whirled cream. It’s loved by a certain Pokémon.",
                "ja": "ふんわり　ふわふわに　あわだてた　ほんのり　あまい　クリーム。　ある　ポケモンが　このんでいる。",
                "es": "Un dulce a base de suave y esponjosa nata montada. A cierto Pokémon le encanta.",
                "fr": "Une crème sucrée qui fond dans la bouche, légère comme un nuage. Elle est appréciée d’un certain Pokémon.",
                "de": "Ein lockeres, leicht süßliches Häubchen aus Schlagsahne, das bei einer bestimmten Pokémon-Art sehr beliebt ist.",
            ]),
        "prism-scale": Entry(appOriginalLanguages: [],
            names: ["ko": "고운비늘", "en": "Prism Scale", "ja": "きれいなウロコ", "es": "Escama Bella", "fr": "Bel’Écaille", "de": "Schönschuppe"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 비늘. 무지갯빛으로 빛나고 있다.",
                "en": "A mysterious scale that causes a certain Pokémon to evolve. It shines in rainbow colors.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　ウロコ。　にじいろに　かがやいている。",
                "es": "Curiosa escama que hace evolucionar a cierto Pokémon. Brilla con los colores del arcoíris.",
                "fr": "Une écaille étrange qui fait évoluer une certaine espèce de Pokémon. Elle a une couleur arc-en-ciel.",
                "de": "Eine seltsame Schuppe, durch die sich ein bestimmtes Pokémon entwickelt. Sie funkelt in den Farben des Regenbogens.",
            ]),
        "red-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "주홍구슬", "en": "Red Orb", "ja": "べにいろのたま", "es": "Prisma Rojo", "fr": "Gemme Rouge", "de": "Roter Edelstein"],
            texts: [
                "ko": "호연지방의 전설과 깊은 연관이 있다고 전해지는 빨갛게 빛나는 구슬.",
                "en": "A shiny red orb that is said to have a legend tied to it. It’s known to have a deep connection with the Hoenn region.",
                "ja": "ホウエンちほうの　でんせつと　ふかい　かかわりが　あると　いわれる　あかく　かがやく　たま。",
                "es": "Piedra carmesí de la que se dice que guarda una estrecha relación con las leyendas de Hoenn.",
                "fr": "Une gemme incarnate dont on dit qu’elle a un lien très étroit avec les légendes de Hoenn.",
                "de": "Ein rot schimmernder Stein, von dem in den Legenden der Hoenn-Region berichtet wird.",
            ]),
        "blue-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "쪽빛구슬", "en": "Blue Orb", "ja": "あいいろのたま", "es": "Prisma Azul", "fr": "Gemme Bleue", "de": "Blauer Edelstein"],
            texts: [
                "ko": "호연지방의 전설과 깊은 연관이 있다고 전해지는 파랗게 빛나는 구슬.",
                "en": "A shiny blue orb that is said to have a legend tied to it. It’s known to have a deep connection with the Hoenn region.",
                "ja": "ホウエンちほうの　でんせつと　ふかい　かかわりが　あると　いわれる　あおく　かがやく　たま。",
                "es": "Piedra añil que, según dicen, guarda una estrecha relación con las leyendas de Hoenn.",
                "fr": "Une gemme céruléenne dont on dit qu’elle a un lien très étroit avec les légendes de Hoenn.",
                "de": "Ein blau schimmernder Stein, von dem in den Legenden der Hoenn-Region berichtet wird.",
            ]),
        "adamant-crystal": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "큰금강옥", "en": "Adamant Crystal", "ja": "だいこんごうだま", "es": "Gran Diamansfera", "fr": "Globe Adamant", "de": "Adamantkristall"],
            texts: [
                "ko": "디아루가가 지니면 오리진폼의 모습이 되는 크게 빛나는 옥. 강철과 드래곤타입 기술의 위력이 올라간다.",
                "en": "A large, glowing gem that lets Dialga change form when held. It boosts the power of Dialga’s Dragon- and Steel-type moves.",
                "ja": "ディアルガに　もたせると　オリジンフォルムの　すがたになる　おおきく　かがやく　たま。　はがねと　ドラゴンタイプの　わざの　いりょくが　あがる。",
                "es": "Una gran gema resplandeciente que permite a Dialga cambiar de forma si la lleva. Potencia sus movimientos de tipo Dragón y Acero.",
                "fr": "Un gros joyau brillant qui permet à Dialga de changer de forme s'il le tient. Augmente la puissance de ses capacités de type Dragon et Acier.",
                "pt": "Uma grande gema brilhante que faz Dialga mudar de forma ao segurá-la. Aumenta o poder dos golpes dos tipos Dragão e Aço de Dialga.",
                "de": "Ein großer, leuchtender Edelstein, der Dialga die Form wechseln lässt, wenn es ihn trägt. Verstärkt seine Drache- und Stahl-Attacken.",
                "ru": "Большой сияющий камень. Если его держит Диалга, он меняет форму, а его атаки типов «Дракон» и «Сталь» становятся сильнее.",
            ]),
        "lustrous-globe": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "큰백옥", "en": "Lustrous Globe", "ja": "だいしらたま", "es": "Gran Lustresfera", "fr": "Globe Perlé", "de": "Weißkristall"],
            texts: [
                "ko": "펄기아가 지니면 오리진폼의 모습이 되는 크게 빛나는 옥. 물과 드래곤타입 기술의 위력이 올라간다.",
                "en": "A large, glowing gem that lets Palkia change form when held. It boosts the power of Palkia’s Dragon- and Water-type moves.",
                "ja": "パルキアに　もたせると　オリジンフォルムの　すがたになる　おおきく　かがやく　たま。　みずと　ドラゴンタイプの　わざの　いりょくが　あがる。",
                "es": "Una gran gema resplandeciente que permite a Palkia cambiar de forma si la lleva. Potencia sus movimientos de tipo Dragón y Agua.",
                "fr": "Un gros joyau brillant qui permet à Palkia de changer de forme s'il le tient. Augmente la puissance de ses capacités de type Dragon et Eau.",
                "pt": "Uma grande gema brilhante que faz Palkia mudar de forma ao segurá-la. Aumenta o poder dos golpes dos tipos Dragão e Água de Palkia.",
                "de": "Ein großer, leuchtender Edelstein, der Palkia die Form wechseln lässt, wenn es ihn trägt. Verstärkt seine Drache- und Wasser-Attacken.",
                "ru": "Большой сияющий камень. Если его держит Палкия, она меняет форму, а её атаки типов «Дракон» и «Вода» становятся сильнее.",
            ]),
        "griseous-core": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "큰백금옥", "en": "Griseous Core", "ja": "だいはっきんだま", "es": "Gran Griseosfera", "fr": "Globe Platiné", "de": "Platinumkristall"],
            texts: [
                "ko": "기라티나가 지니면 오리진폼의 모습이 되는 크게 빛나는 옥. 고스트와 드래곤타입 기술의 위력이 올라간다.",
                "en": "A large, glowing gem that lets Giratina change form when held. It boosts the power of Giratina’s Dragon- and Ghost-type moves.",
                "ja": "ギラティナに　もたせると　オリジンフォルムの　すがたになる　おおきく　かがやく　たま。　ゴーストと　ドラゴンタイプの　わざの　いりょくが　あがる。",
                "es": "Una gran gema resplandeciente que permite a Giratina cambiar de forma si la lleva. Potencia sus movimientos de tipo Dragón y Fantasma.",
                "fr": "Un gros joyau brillant qui permet à Giratina de changer de forme s'il le tient. Augmente la puissance de ses capacités de type Dragon et Spectre.",
                "pt": "Uma grande gema brilhante que faz Giratina mudar de forma ao segurá-la. Aumenta o poder dos golpes dos tipos Dragão e Fantasma de Giratina.",
                "de": "Ein großer, leuchtender Edelstein, der Giratina die Form wechseln lässt, wenn es ihn trägt. Verstärkt seine Drache- und Geist-Attacken.",
                "ru": "Большой сияющий камень. Если его держит Гиратина, она меняет форму, а её атаки типов «Дракон» и «Призрак» становятся сильнее.",
            ]),
        "punching-glove": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "펀치글러브", "en": "Punching Glove", "ja": "パンチグローブ", "es": "Guante de Boxeo", "fr": "Gant de Boxe", "de": "Boxhandschuh"],
            texts: [
                "ko": "펀치를 보호하는 글러브. 지니게 하면 펀치 기술의 위력이 올라간다.",
                "en": "A protective glove. It boosts the power of the holder’s punching moves.",
                "ja": "パンチを　まもる　グローブ。　もたせると　パンチわざの　いりょくが　あがる。",
                "es": "Un guante protector. Potencia los movimientos de puño del portador.",
                "fr": "Un gant protecteur. Augmente la puissance des capacités de poing du porteur.",
                "pt": "Uma luva protetora. Aumenta o poder dos golpes de soco do portador.",
                "de": "Ein Schutzhandschuh. Verstärkt die Schlag-Attacken des Trägers.",
                "ru": "Защитная перчатка. Усиливает удары кулаком у того, кто её держит.",
            ]),
        "rusted-sword": Entry(appOriginalLanguages: [],
            names: ["ko": "녹슨검", "en": "Rusted Sword", "ja": "くちたけん", "es": "Espada Oxidada", "fr": "Épée Rouillée", "de": "Rostiges Schwert"],
            texts: [
                "ko": "먼 옛날의 영웅이 재앙을 막는 데 사용했다고 전해지는 검이지만 지금은 녹이 슬고 닳아버렸다.",
                "en": "It is said that a hero used this sword to halt a terrible disaster in ancient times. But it’s grown rusty and worn.",
                "ja": "おおむかしの　えいゆうが　さいやくを　うちはらったと　つたえられる　けん　だが　いまは　さびて　ボロボロに　なっている。",
                "es": "Cuenta una antigua leyenda que un valiente héroe blandió esta espada para hacer frente a un cataclismo, pero ahora está oxidada y en un estado lamentable.",
                "fr": "On raconte que cette épée fut jadis utilisée par un héros pour vaincre une calamité. À présent, elle est toute usée et rouillée.",
                "de": "Mit diesem Schwert soll ein Held einstmals großes Unheil abgewendet haben. Rost sowie der Zahn der Zeit haben jedoch ihre Spuren hinterlassen.",
            ]),
        "rusted-shield": Entry(appOriginalLanguages: [],
            names: ["ko": "녹슨방패", "en": "Rusted Shield", "ja": "くちたたて", "es": "Escudo Oxidado", "fr": "Bouclier Rouillé", "de": "Rostiger Schild"],
            texts: [
                "ko": "먼 옛날의 영웅이 재앙을 막는 데 사용했다고 전해지는 방패지만 지금은 녹이 슬고 닳아버렸다.",
                "en": "It is said that a hero used this shield to halt a terrible disaster in ancient times. But it’s grown rusty and worn.",
                "ja": "おおむかしの　えいゆうが　さいやくを　うちはらったと　つたえられる　たて　だが　いまは　さびて　ボロボロに　なっている。",
                "es": "Cuenta una antigua leyenda que un valiente héroe asió este escudo para hacer frente a un cataclismo, pero ahora está oxidado y en un estado lamentable.",
                "fr": "On raconte que ce bouclier fut jadis utilisé par un héros pour vaincre une calamité. À présent, il est tout usé et rouillé.",
                "de": "Mit diesem Schild soll ein Held einstmals großes Unheil abgewendet haben. Rost sowie der Zahn der Zeit haben jedoch ihre Spuren hinterlassen.",
            ]),
        "ultranecrozium-z--held": Entry(appOriginalLanguages: [],
            names: ["ko": "울트라네크로Z", "en": "Ultranecrozium Z", "ja": "ウルトラネクロＺ", "es": "Ultranecrostal Z", "fr": "Ultranécrozélite", "de": "Ultranecronium Z"],
            texts: [
                "ko": "Z파워의 결정. 네크로즈마의 포톤가이저를 Z기술로 업그레이드한다.",
                "en": "This is a crystallized form of Z-Power. It upgrades Necrozma’s Photon Geyser to a Z-Move.",
                "ja": "Ｚパワーの　けっしょう。　ネクロズマの　フォトンゲイザーを　Ｚワザに　グレードアップする。",
                "es": "Cristal que confiere el Poder Z al movimiento Géiser Fotónico de Necrozma.",
                "fr": "Une cristallisation de la Force Z, permettant de transformer le Photo-Geyser de Necrozma en capacité Z.",
                "de": "Ein Kristall, dem Z-Kraft innewohnt. Er stuft Necrozmas Attacke Photonen-Geysir zu einer Z-Attacke auf.",
            ]),
        "occa-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "오카열매", "en": "Occa Berry", "ja": "オッカのみ", "es": "Baya Caoca", "fr": "Baie Chocco", "de": "Koakobeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 효과가 뛰어난 불꽃 기술을 당했을 때 위력이 약해진다.",
                "en": "If held by a Pokémon, this Berry will lessen the damage taken from one supereffective Fire-type attack.",
                "ja": "ポケモンに　もたせると　こうかばつぐんの　ほのお　わざを　うけたとき　いりょくが　よわまる。",
                "es": "Si la lleva un Pokémon, debilita un ataque supereficaz de tipo Fuego de un enemigo.",
                "fr": "Tenue, cette Baie affaiblit une attaque ennemie super efficace de type Feu.",
