        "ability-capsule": Entry(appOriginalLanguages: [],
            names: ["ko": "특성캡슐", "en": "Ability Capsule", "ja": "とくせいカプセル", "es": "Cáps. Habilidad", "fr": "Pilule Talent", "de": "Fähigkeiten-Kapsel"],
            texts: [
                "ko": "2종류의 특성을 가진 포켓몬에게 사용하면 지금과는 다른 특성으로 바꿀 수 있는 캡슐.",
                "en": "A capsule that allows a Pokémon with two Abilities to switch between these Abilities when it is used.",
                "ja": "２しゅるいの　とくせいを　もつ　ポケモンに　つかうと　いまとはちがう　とくせいに　かえられる　カプセル。",
                "es": "Cápsula que les permite cambiar de habilidad a los Pokémon que poseen dos.",
                "fr": "Une capsule permettant à un Pokémon pouvant avoir deux talents de passer de l’un à l’autre.",
                "de": "Bei Anwendung auf ein Pokémon, das zwei verschiedene Fähigkeiten haben kann, wird seine aktuelle Fähigkeit mit der anderen ausgewechselt.",
            ]),
        "ability-patch": Entry(appOriginalLanguages: [],
            names: ["ko": "특성패치", "en": "Ability Patch", "ja": "とくせいパッチ", "es": "Parche Habilidad", "fr": "Patch Talent", "de": "Fähigkeiten-Pflaster"],
            texts: [
                "ko": "일반적인 특성을 가진 포켓몬에게 사용하면 희귀한 특성으로 바꿀 수 있는 패치.",
                "en": "A patch that allows a Pokémon with a regular Ability to have a rare Ability.",
                "ja": "つうじょうの　とくせいを　もつ　ポケモンに　つかうと　めずらしい　とくせいに　かえられる　パッチ。",
                "es": "Parche que permite cambiar la habilidad normal de un Pokémon a otra menos común.",
                "fr": "Un objet qui permet de remplacer le talent ordinaire d’un Pokémon par un talent rare.",
                "de": "Ein Pflaster, das es ermöglicht, die reguläre Fähigkeit eines Pokémon zu einer seltenen Fähigkeit zu ändern.",
            ]),
        "bottle-cap": Entry(appOriginalLanguages: [],
            names: ["ko": "은색병뚜껑", "en": "Bottle Cap", "ja": "ぎんのおうかん", "es": "Chapa Plateada", "fr": "Capsule d’Argent", "de": "Silberkronkorken"],
            texts: [
                "ko": "은색의 아름다운 왕관. 받으면 좋아하는 사람도 있다.",
                "en": "A beautiful bottle cap that gives off a silver gleam. Some people are happy to receive one.",
                "ja": "ぎんいろの　きれいな　おうかん。　わたすと　よろこぶ　ひともいる。",
                "es": "Una bonita chapa de color plata. Hay gente que las aprecia mucho.",
                "fr": "Une jolie capsule en argent. Certaines personnes adorent en recevoir.",
                "de": "Ein hübscher silberner Kronkorken. Es gibt Leute, die sich sehr darüber freuen würden!",
            ]),
        "gold-bottle-cap": Entry(appOriginalLanguages: [],
            names: ["ko": "금색병뚜껑", "en": "Gold Bottle Cap", "ja": "きんのおうかん", "es": "Chapa Dorada", "fr": "Capsule d’Or", "de": "Goldkronkorken"],
            texts: [
                "ko": "금색의 아름다운 왕관. 은왕관보다 진귀하다. 받으면 좋아하는 사람도 있다.",
                "en": "A beautiful bottle cap that gives off a golden gleam. Some people are happy to receive one.",
                "ja": "きんいろの　きれいな　おうかん。　ぎんのおうかんより　めずらしい。　わたすと　よろこぶ　ひともいる。",
                "es": "Una bonita chapa de color dorado, menos común que su equivalente plateada. Hay gente que las aprecia mucho.",
                "fr": "Une jolie capsule en or, encore plus rare que la Capsule d’Argent. Certaines personnes adorent en recevoir.",
                "de": "Ein hübscher goldener Kronkorken. Er ist noch seltener als ein Silberkronkorken. Es gibt Leute, die sich sehr darüber freuen würden!",
            ]),
