            names: ["ko": "비추는거울", "en": "Reveal Glass", "ja": "うつしかがみ", "es": "Espejo Veraz", "fr": "Miroir Sacré", "de": "Wahrspiegel"],
            texts: [
                "ko": "진실을 비춰줌으로 포켓몬을 본래의 모습으로 바꿔버리는 이상한 거울.",
                "en": "A looking glass that reveals the truth. It’s a mysterious glass that returns a Pokémon to its original shape.",
                "ja": "しんじつを　うつしだすことで　ポケモンを　ほんらいの　すがたに　かえてしまう　ふしぎな　かがみ。",
                "es": "Espejo misterioso que refleja la verdad y devuelve los Pokémon a su forma original.",
                "fr": "Un mystérieux miroir qui, en reflétant la vérité, permet de redonner à un Pokémon sa forme originelle.",
                "de": "Ein mysteriöser Spiegel, der Pokémon in ihre eigentliche Form verwandelt, indem er die Wahrheit widerspiegelt.",
            ]),
        "dna-splicers": Entry(appOriginalLanguages: [],
            names: ["ko": "유전자쐐기", "en": "DNA Splicers", "ja": "いでんしのくさび", "es": "Punta ADN", "fr": "Pointeau ADN", "de": "DNS-Keil"],
            texts: [
                "ko": "원래는 하나였다고 전해지는 큐레무와 어떤 포켓몬을 합체시키는 한 쌍의 쐐기.",
                "en": "A splicer that fuses Kyurem and a certain Pokémon. They are said to have been one in the beginning.",
                "ja": "もとは　ひとつだったと　いわれる　キュレムと　あるポケモンを　がったいさせる　いっついの　くさび。",
                "es": "Punta que permite fusionar a Kyurem con cierto Pokémon con el que, originariamente, formaba un solo ser.",
                "fr": "Un outil qui permet la fusiorption de Kyurem et d’un autre Pokémon avec lequel il ne faisait qu’un à l’origine.",
                "de": "Ein Keil, der Kyurem und ein gewisses anderes Pokémon, die vermeintlich einst eins gewesen sind, vereinigt.",
            ]),
        "reins-of-unity": Entry(appOriginalLanguages: [],
            names: ["ko": "유대의고삐", "en": "Reins of Unity", "ja": "キズナのタヅナ", "es": "Riendas Unión", "fr": "Rênes de l’Unité", "de": "Zügel des Bundes"],
            texts: [
                "ko": "빛에 비추면 반짝이는 천. 과거에 인간들이 풍요의 왕에게 감사하는 마음을 담아 바쳤다고 한다.",
                "en": "Cords that shine when you hold them up to the light. The people of old times presented these to the King of Bountiful Harvests to express their gratitude.",
                "ja": "ひかりに　かざすと　かがやく　ぬの。　むかし　にんげんが　ほうじょうのおうに　かんしゃの　きもちとして　ささげていた。",
                "es": "Correas elaboradas con un tejido que brilla bajo la luz. En el pasado, los humanos las entregaban como ofrenda al Rey de las Cosechas en señal de gratitud.",
                "fr": "Une courroie faite d’un tissu qui scintille à la lumière. Les humains en offraient autrefois au Seigneur des récoltes en gage de leur gratitude.",
                "de": "Zügel gewoben aus Stoff, der leuchtet, wenn man ihn ins Licht hält. Einst schenkten die Menschen sie dem König der reichen Ernte als Zeichen ihrer Dankbarkeit.",
            ]),
        "mirror-herb": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "흉내허브", "en": "Mirror Herb", "ja": "ものまねハーブ", "es": "Hierba Copia", "fr": "Feuille Copieuse", "de": "Kopierkraut"],
            texts: [
                "ko": "흉내 내기를 돕는 신기한 허브. 먹은 포켓몬은 알에서만 배우는 기술을 익힐 수 있게 된다.",
                "en": "A curious herb that helps a Pokémon mimic others. One that eats it becomes able to learn the moves its kind learns only as an Egg.",
                "ja": "まねを　たすける　ふしぎな　ハーブ。たべた　ポケモンは　タマゴでしか　おぼえない　わざを　おぼえられるように　なる。",
                "es": "Una hierba curiosa que ayuda a imitar. El Pokémon que la come puede aprender los movimientos que su especie solo aprende como Huevo.",
                "fr": "Une herbe étrange qui aide à imiter. Le Pokémon qui la mange peut apprendre les capacités que son espèce n'apprend que dans l'Œuf.",
                "pt": "Uma erva curiosa que ajuda a imitar. O Pokémon que a come passa a aprender os golpes que sua espécie só aprende como Ovo.",
                "de": "Ein seltsames Kraut, das beim Nachahmen hilft. Ein Pokémon, das es frisst, kann Attacken erlernen, die seine Art nur als Ei lernt.",
                "ru": "Странная трава, помогающая подражать. Съевший её покемон может учить приёмы, которые его вид учит только в яйце.",
            ]),
        "ability-shield": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "특성가드", "en": "Ability Shield", "ja": "とくせいガード", "es": "Escudo Habilidad", "fr": "Garde-Talent", "de": "Fähigkeitenschild"],
            texts: [
                "ko": "특성을 지키는 방패. 지니게 하면 다른 포켓몬이나 기술에 특성이 바뀌거나 지워지지 않는다.",
                "en": "A shield that protects the holder’s Ability. Other Pokémon and moves can’t change or suppress it.",
                "ja": "とくせいを　まもる　たて。　もたせると　ほかの　ポケモンや　わざに　とくせいを　かえられたり　けされたり　しない。",
                "es": "Un escudo que protege la habilidad del portador. Nadie puede cambiarla ni anularla.",
                "fr": "Un bouclier qui protège le talent du porteur. Rien ne peut le changer ni l'annuler.",
                "pt": "Um escudo que protege a habilidade do portador. Nada pode trocá-la nem anulá-la.",
                "de": "Ein Schild, der die Fähigkeit des Trägers schützt. Sie kann weder getauscht noch unterdrückt werden.",
                "ru": "Щит, защищающий способность носителя. Её нельзя сменить или подавить.",
            ]),
        "absorb-bulb": Entry(appOriginalLanguages: [],
            names: ["ko": "구근", "en": "Absorb Bulb", "ja": "きゅうこん", "es": "Tubérculo", "fr": "Bulbe", "de": "Knolle"],
            texts: [
                "ko": "단 한 번 쓰면 없어지는 구근. 지니게 하고 물 기술을 받으면 특수공격이 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Sp. Atk if the holder is hit with a Water-type attack. It can only be used once.",
                "ja": "つかいすての　きゅうこん。　もたせて　みずの　わざを　うけると　とくこうが　あがる。",
                "es": "Aumenta el Ataque Especial del portador si le alcanza un ataque de tipo Agua. Desaparece tras usarlo.",
                "fr": "Objet à tenir. Un bulbe jetable qui augmente l’Attaque Spéciale du porteur lorsqu’il encaisse une attaque de type Eau.",
                "de": "Eine einmalig einsetzbare Knolle. Erhöht den Spezial-Angriff des Trägers, wenn ihn eine Wasser-Attacke trifft.",
            ]),
        "adamant-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "금강옥", "en": "Adamant Orb", "ja": "こんごうだま", "es": "Diamansfera", "fr": "Orbe Adamant", "de": "Adamant-Orb"],
            texts: [
                "ko": "디아루가에게 지니게 하면 드래곤과 강철타입 기술의 위력이 올라가는 반짝반짝 빛나는 구슬.",
                "en": "A brightly gleaming orb to be held by Dialga. It boosts the power of Dragon- and Steel-type moves when it is held.",
                "ja": "ディアルガに　もたせると　ドラゴンと　はがねタイプの　わざの　いりょくが　あがる　ひかり　かがやく　たま。",
                "es": "Una esfera brillante que potencia los movimientos de tipo Acero y Dragón. Debe llevarla Dialga.",
                "fr": "Un orbe très brillant destiné à Dialga. Augmente la puissance des capacités de types Dragon et Acier.",
                "de": "Ein hell leuchtender Orb. Verstärkt Attacken vom Typ Drache und Stahl, wenn Dialga ihn trägt.",
            ]),
        "adrenaline-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "주눅구슬", "en": "Adrenaline Orb", "ja": "ビビリだま", "es": "Nerviosfera", "fr": "Orbe Frousse", "de": "Zitter-Orb"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위협을 받았을 때 스피드가 올라간다.",
                "en": "If held by a Pokémon, it boosts Speed when intimidated.",
                "ja": "ポケモンに　もたせると　いかくを　うけたとき　すばやさが　あがる。",
                "es": "Aumenta la Velocidad del portador si se siente intimidado.",
                "fr": "Objet à tenir. Si le porteur subit une Intimidation, sa Vitesse augmente.",
                "de": "Als getragenes Item erhöht er bei Pokémon, die unter dem Einfluss von Bedroher stehen, die Initiative.",
            ]),
        "aguav-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "아바열매", "en": "Aguav Berry", "ja": "バンジのみ", "es": "Baya Guaya", "fr": "Baie Gowav", "de": "Gauvebeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 HP를 회복한다. 싫어하는 맛이면 혼란에 빠진다.",
                "en": "If held by a Pokémon, it restores the user’s HP in a pinch, but it will cause confusion if the user hates the taste.",
                "ja": "ポケモンに　もたせると　ピンチのとき　ＨＰを　かいふくする。　きらいな　あじだと　こんらん　する。",
                "es": "Los Pokémon pueden llevarla o usarla para restaurar algunos PS. Su sabor puede causar confusión si no les gusta.",
                "fr": "Tenue, cette Baie restaure des PV en cas de besoin, mais rend le Pokémon confus si son goût lui déplaît.",
                "de": "Als getragenes Item füllt die Beere im Notfall die KP eines Pokémon auf, doch ihr Aroma verwirrt jene, die es nicht mögen.",
            ]),
        "air-balloon": Entry(appOriginalLanguages: [],
            names: ["ko": "풍선", "en": "Air Balloon", "ja": "ふうせん", "es": "Globo Helio", "fr": "Ballon", "de": "Luftballon"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 포켓몬이 허공에 뜬다. 공격을 받으면 터져버린다.",
                "en": "An item to be held by a Pokémon. The holder will float in the air until hit. Once the holder is hit, this item will burst.",
                "ja": "ポケモンに　もたせると　ポケモンが　ちゅうに　うく。　こうげきを　うけると　われてしまう。",
                "es": "El Pokémon que lo lleve flotará en el aire. Si recibe un golpe, estallará.",
                "fr": "Objet à tenir. Permet au porteur de flotter dans les airs. Il éclate quand le porteur encaisse une attaque.",
                "de": "Gibt man ihn einem Pokémon zum Tragen, fängt es an zu schweben. Wird es getroffen, platzt der Luftballon.",
            ]),
        "apicot-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "규살열매", "en": "Apicot Berry", "ja": "ズアのみ", "es": "Baya Aricoc", "fr": "Baie Abriko", "de": "Apikobeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 자신의 특수방어가 올라간다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, its Sp. Def stat will increase when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　じぶんの　とくぼうが　あがる。",
                "es": "Si la lleva un Pokémon, le sube la Defensa Especial en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente la Défense Spéciale en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere den Spezial-Verteidigungs-Wert eines Pokémon, sobald es in einer Notlage steckt.",
            ]),
        "aspear-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "배리열매", "en": "Aspear Berry", "ja": "ナナシのみ", "es": "Baya Perasi", "fr": "Baie Willia", "de": "Wilbirbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 얼음을 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can recover from being frozen on its own in battle.",
                "ja": "ポケモンに　もたせると　こおりを　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para descongelarse.",
                "fr": "Une Baie qui soigne le gel lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, taut diese es auf, wenn es eingefroren wird.",
            ]),
        "binding-band": Entry(appOriginalLanguages: [],
            names: ["ko": "조임밴드", "en": "Binding Band", "ja": "しめつけバンド", "es": "Banda Atadura", "fr": "Bande Étreinte", "de": "Klammerband"],
            texts: [
                "ko": "조이기 기술을 보조하는 밴드. 지니게 하면 조이기 기술의 위력이 강해진다.",
                "en": "An item to be held by a Pokémon. It’s a band that increases the power of binding moves used by the holder.",
                "ja": "しめつけるわざを　ほじょする　バンド。　もたせると　しめつけるわざの　いりょくが　つよく　なる。",
                "es": "Banda que potencia los movimientos que estrujan al rival.",
                "fr": "Objet à tenir. Augmente la puissance des attaques immobilisantes telles que Ligotage ou Étreinte.",
                "de": "Ein Band, das die Stärke aller Klammerattacken des Trägers erhöht.",
            ]),
        "blunder-policy": Entry(appOriginalLanguages: [],
            names: ["ko": "허탕보험", "en": "Blunder Policy", "ja": "からぶりほけん", "es": "Seguro Fallo", "fr": "Assurance Échec", "de": "Fehlschlagschutz"],
            texts: [
                "ko": "명중률에 의해 기술이 빗나갔을 때 스피드가 크게 올라간다.",
                "en": "Raises Speed sharply when a Pokémon misses with a move because of accuracy.",
                "ja": "めいちゅうりつに　よって　わざが　はずれたとき　すばやさが　ぐーんと　あがる。",
                "es": "Aumenta mucho la Velocidad cuando el Pokémon yerra el movimiento debido a la precisión.",
                "fr": "Si un Pokémon manque sa cible parce qu’une capacité a peu de Précision, sa Vitesse augmente beaucoup.",
                "de": "Schlägt eine Attacke des Anwenders mangels Genauigkeit fehl, steigt im Gegenzug dessen Initiative stark an.",
            ]),
        "booster-energy": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "부스트에너지", "en": "Booster Energy", "ja": "ブーストエナジー", "es": "Energía Potenciadora", "fr": "Énergie Booster", "de": "Energiekapsel"],
            texts: [
                "ko": "에너지가 가득 찬 캡슐. 고대활성이나 쿼크차지 특성을 가진 포켓몬에게 지니게 하면 특성이 발동한다.",
                "en": "A capsule filled with energy. It activates the Protosynthesis or Quark Drive Ability of the Pokémon holding it.",
                "ja": "エネルギーが　つまった　カプセル。　こだいかっせいや　クォークチャージの　ポケモンに　もたせると　とくせいが　はつどうする。",
                "es": "Una cápsula llena de energía. Activa la habilidad Paleosíntesis o Carga Cuark del portador.",
                "fr": "Une capsule pleine d'énergie. Active le talent Paléosynthèse ou Charge Quantique du porteur.",
                "pt": "Uma cápsula cheia de energia. Ativa a habilidade Paleossíntese ou Carga Quark do portador.",
                "de": "Eine Kapsel voller Energie. Aktiviert die Fähigkeit Paläosynthese oder Quantenantrieb des Trägers.",
                "ru": "Капсула, полная энергии. Включает способность «Протосинтез» или «Кварковый привод» носителя.",
            ]),
        "bug-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "벌레주얼", "en": "Bug Gem", "ja": "むしのジュエル", "es": "Gema Bicho", "fr": "Joyau Insecte", "de": "Käferjuwel"],
            texts: [
                "ko": "벌레타입의 주얼. 지니게 하면 한 번만 벌레 기술의 위력이 강해진다.",
                "en": "A gem with an insect-like essence. When held, it strengthens the power of a Bug-type move one time.",
                "ja": "むしの　タイプの　ジュエル。　もたせると　いちどだけ　むしの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Bicho. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Insecte.",
                "de": "Ein Juwel vom Typ Käfer. Es erhöht einmalig die Stärke einer Attacke vom Typ Käfer.",
            ]),
        "bug-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "버그메모리", "en": "Bug Memory", "ja": "バグメモリ", "es": "Disco Bicho", "fr": "ROM Insecte", "de": "Käfer-Disc"],
            texts: [
                "ko": "벌레타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Bug-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "むしタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Bicho. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Insecte. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Käfer. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "burn-drive": Entry(appOriginalLanguages: [],
            names: ["ko": "블레이즈카세트", "en": "Burn Drive", "ja": "ブレイズカセット", "es": "PiroROM", "fr": "Module Pyro", "de": "Flammenmodul"],
            texts: [
                "ko": "게노세크트에게 지니게 하면 테크노버스터라는 기술이 불꽃타입으로 바뀌는 카세트.",
                "en": "A cassette to be held by Genesect. It changes Genesect’s Techno Blast move so it becomes Fire type.",
                "ja": "ゲノセクトに　もたせると　テクノバスターという　わざが　ほのおタイプになる　カセット。",
                "es": "Cartucho que convierte Tecno Shock de Genesect en un movimiento de tipo Fuego.",
                "fr": "Tenu par Genesect, ce module change la capacité Techno-Buster en une capacité de type Feu.",
                "de": "Gibt man es Genesect zum Tragen, wandelt es den Typ der Attacke Techblaster in Feuer um.",
            ]),
        "cell-battery": Entry(appOriginalLanguages: [],
            names: ["ko": "충전지", "en": "Cell Battery", "ja": "じゅうでんち", "es": "Pila", "fr": "Pile", "de": "Akku"],
            texts: [
                "ko": "단 한 번 쓰면 없어지는 충전지. 지니게 하고 전기 기술을 받으면 공격이 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Attack if the holder is hit with an Electric-type attack. It can only be used once.",
                "ja": "つかいすての　じゅうでんち。　もたせて　でんきの　わざを　うけると　こうげきが　あがる。",
                "es": "Batería de usar y tirar que sube el Ataque de quien la lleva cuando recibe un golpe de tipo Eléctrico.",
                "fr": "Objet à tenir. Une pile jetable qui augmente l’Attaque du porteur lorsqu’il encaisse une attaque de type Électrik.",
                "de": "Ein einmalig aufladbarer Akku. Erhöht den Angriff des Trägers, wenn ihn eine Elektro-Attacke trifft.",
            ]),
        "cheri-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "버치열매", "en": "Cheri Berry", "ja": "クラボのみ", "es": "Baya Zreza", "fr": "Baie Ceriz", "de": "Amrenabeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 마비를 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can recover from paralysis on its own in battle.",
                "ja": "ポケモンに　もたせると　まひを　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para recuperarse de la parálisis.",
                "fr": "Une Baie qui soigne la paralysie lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, heilt diese es von Paralyse.",
            ]),
        "chesto-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "유루열매", "en": "Chesto Berry", "ja": "カゴのみ", "es": "Baya Atania", "fr": "Baie Maron", "de": "Maronbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 잠듦을 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can recover from sleep on its own in battle.",
                "ja": "ポケモンに　もたせると　ねむりを　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para despertar del sueño.",
                "fr": "Une Baie qui soigne le sommeil lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, erwacht es dadurch aus dem Schlaf.",
            ]),
        "chill-drive": Entry(appOriginalLanguages: [],
            names: ["ko": "프리즈카세트", "en": "Chill Drive", "ja": "フリーズカセット", "es": "CrioROM", "fr": "Module Cryo", "de": "Gefriermodul"],
            texts: [
                "ko": "게노세크트에게 지니게 하면 테크노버스터라는 기술이 얼음타입으로 바뀌는 카세트.",
                "en": "A cassette to be held by Genesect. It changes Genesect’s Techno Blast move so it becomes Ice type.",
                "ja": "ゲノセクトに　もたせると　テクノバスターという　わざが　こおりタイプになる　カセット。",
                "es": "Cartucho que convierte Tecno Shock de Genesect en un movimiento de tipo Hielo.",
                "fr": "Tenu par Genesect, ce module change la capacité Techno-Buster en une capacité de type Glace.",
                "de": "Gibt man es Genesect zum Tragen, wandelt es den Typ der Attacke Techblaster in Eis um.",
            ]),
        "clear-amulet": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "클리어참", "en": "Clear Amulet", "ja": "クリアチャーム", "es": "Amuleto Puro", "fr": "Talisman Sain", "de": "Neutralschmuck"],
            texts: [
                "ko": "맑게 빛나는 부적. 지니게 하면 상대의 기술이나 특성 때문에 능력이 떨어지지 않는다.",
                "en": "A clear, shining amulet. Other Pokémon’s moves and Abilities can’t lower the holder’s stats.",
                "ja": "すきとおって　かがやく　おまもり。　もたせると　あいての　わざや　とくせいで　のうりょくが　さがらない。",
                "es": "Un amuleto claro y brillante. Los movimientos y habilidades rivales no pueden bajar las características del portador.",
                "fr": "Une amulette claire et brillante. Les capacités et talents adverses ne peuvent pas baisser les stats du porteur.",
                "pt": "Um amuleto claro e brilhante. Golpes e habilidades inimigas não podem reduzir os atributos do portador.",
                "de": "Ein klares, glänzendes Amulett. Gegnerische Attacken und Fähigkeiten können die Werte des Trägers nicht senken.",
                "ru": "Прозрачный сияющий амулет. Атаки и способности соперника не могут понизить характеристики носителя.",
            ]),
        "covert-cloak": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "은밀망토", "en": "Covert Cloak", "ja": "おんみつマント", "es": "Capa Furtiva", "fr": "Cape Obscure", "de": "Tarnumhang"],
            texts: [
                "ko": "몸을 감싸 숨기는 망토. 지니게 하면 기술의 추가 효과를 받지 않는다.",
                "en": "A hooded cloak that conceals the holder. It protects the holder from the added effects of moves.",
                "ja": "からだを　つつんで　かくす　マント。　もたせると　わざの　ついかこうかを　うけない。",
                "es": "Una capa con capucha que oculta al portador. Lo protege de los efectos secundarios de los movimientos.",
                "fr": "Une cape à capuche qui dissimule le porteur. Le protège des effets secondaires des capacités.",
                "pt": "Uma capa com capuz que esconde o portador. Protege-o dos efeitos secundários dos golpes.",
                "de": "Ein Kapuzenumhang, der den Träger verbirgt. Schützt ihn vor den Zusatzeffekten von Attacken.",
                "ru": "Плащ с капюшоном, скрывающий носителя. Защищает от дополнительных эффектов атак.",
            ]),
        "custap-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "애슈열매", "en": "Custap Berry", "ja": "イバンのみ", "es": "Baya Chiri", "fr": "Baie Chérim", "de": "Eipfelbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 한 번만 행동이 빨라진다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it will be able to move first just once when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　いちどだけ　こうどうが　はやくなる。",
                "es": "El Pokémon que la lleva puede actuar en primer lugar una vez cuando se encuentra en un momento de apuro.",
                "fr": "Tenue, cette Baie permet d’utiliser une capacité en priorité une fois en cas de besoin.",
                "de": "Als getragenes Item ermöglicht diese Beere dem Träger in einer Notlage den Erstschlag.",
            ]),
        "dark-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "악주얼", "en": "Dark Gem", "ja": "あくのジュエル", "es": "Gema Siniestra", "fr": "Joyau Ténèbres", "de": "Unlichtjuwel"],
            texts: [
                "ko": "악타입의 주얼. 지니게 하면 한 번만 악 기술의 위력이 강해진다.",
                "en": "A gem with an essence of darkness. When held, it strengthens the power of a Dark-type move one time.",
                "ja": "あくの　タイプの　ジュエル。　もたせると　いちどだけ　あくの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Siniestro. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Ténèbres.",
                "de": "Ein Juwel vom Typ Unlicht. Es erhöht einmalig die Stärke einer Attacke vom Typ Unlicht.",
            ]),
        "dark-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "다크메모리", "en": "Dark Memory", "ja": "ダークメモリ", "es": "Disco Siniestro", "fr": "ROM Ténèbres", "de": "Unlicht-Disc"],
            texts: [
                "ko": "악타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Dark-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "あくタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Siniestro. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Ténèbres. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Unlicht. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "douse-drive": Entry(appOriginalLanguages: [],
            names: ["ko": "아쿠아카세트", "en": "Douse Drive", "ja": "アクアカセット", "es": "HidroROM", "fr": "Module Aqua", "de": "Aquamodul"],
            texts: [
                "ko": "게노세크트에게 지니게 하면 테크노버스터라는 기술이 물타입으로 바뀌는 카세트.",
                "en": "A cassette to be held by Genesect. It changes Genesect’s Techno Blast move so it becomes Water type.",
                "ja": "ゲノセクトに　もたせると　テクノバスターという　わざが　みずタイプになる　カセット。",
                "es": "Cartucho que convierte Tecno Shock de Genesect en un movimiento de tipo Agua.",
                "fr": "Tenu par Genesect, ce module change la capacité Techno-Buster en une capacité de type Eau.",
                "de": "Gibt man es Genesect zum Tragen, wandelt es den Typ der Attacke Techblaster in Wasser um.",
            ]),
        "dragon-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "드래곤주얼", "en": "Dragon Gem", "ja": "ドラゴンジュエル", "es": "Gema Dragón", "fr": "Joyau Dragon", "de": "Drakojuwel"],
            texts: [
                "ko": "드래곤타입의 주얼. 지니게 하면 한 번만 드래곤 기술의 위력이 강해진다.",
