        "electric-seed": Entry(appOriginalLanguages: [],
            names: ["ko": "일렉트릭시드", "en": "Electric Seed", "ja": "エレキシード", "es": "Semilla Electro", "fr": "Graine Électrik", "de": "Elektro-Samen"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 일렉트릭필드일 때 사용하여 방어가 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Defense on Electric Terrain. It can only be used once.",
                "ja": "ポケモンに　もたせると　エレキフィールドのときに　つかって　ぼうぎょが　あがる。",
                "es": "Aumenta la Defensa del portador si se usa cuando el terreno está cubierto por un campo eléctrico.",
                "fr": "Objet à tenir. Augmente la Défense lorsque le terrain est couvert d’un Champ Électrifié.",
                "de": "Gibst du den Samen einem Pokémon zum Tragen, setzt es ihn ein, wenn ein Elektrofeld aktiv ist, und erhöht dadurch seine Verteidigung.",
            ]),
        "enigma-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "의문열매", "en": "Enigma Berry", "ja": "ナゾのみ", "es": "Baya Enigma", "fr": "Baie Enigma", "de": "Enigmabeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 효과가 뛰어난 공격을 받았을 때 HP를 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, being hit by a supereffective attack will restore its HP.",
                "ja": "ポケモンに　もたせると　こうかばつぐんの　わざを　うけたとき　ＨＰを　かいふくする。",
                "es": "Restaura los PS de un Pokémon si la lleva cuando le alcanza un ataque supereficaz.",
                "fr": "Tenue, cette Baie restaure les PV du Pokémon s’il subit une attaque super efficace.",
                "de": "Als getragenes Item füllt diese Beere die KP eines Pokémon auf, wenn es von sehr effektiven Attacken getroffen wird.",
            ]),
        "fairy-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "페어리주얼", "en": "Fairy Gem", "ja": "ようせいジュエル", "es": "Gema Hada", "fr": "Joyau Fée", "de": "Feenjuwel"],
