        "float-stone": Entry(appOriginalLanguages: [],
            names: ["ko": "가벼운돌", "en": "Float Stone", "ja": "かるいし", "es": "Piedra Pómez", "fr": "Pierrallégée", "de": "Leichtstein"],
            texts: [
                "ko": "매우 가벼운 돌. 지니게 하면 포켓몬의 체중이 가벼워진다.",
                "en": "An item to be held by a Pokémon. This very light stone reduces the weight of a Pokémon when held.",
