                "ja": "ひこうの　タイプの　ジュエル。　もたせると　いちどだけ　ひこうの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Volador. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Vol.",
                "de": "Ein Juwel vom Typ Flug. Es erhöht einmalig die Stärke einer Attacke vom Typ Flug.",
            ]),
        "flying-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "플라잉메모리", "en": "Flying Memory", "ja": "フライングメモリ", "es": "Disco Volador", "fr": "ROM Vol", "de": "Flug-Disc"],
            texts: [
                "ko": "비행타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Flying-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "ひこうタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Volador. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Vol. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Flug. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "full-incense": Entry(appOriginalLanguages: [],
            names: ["ko": "만복향로", "en": "Full Incense", "ja": "まんぷくおこう", "es": "Incienso Lento", "fr": "Encens Plein", "de": "Lahmrauch"],
            texts: [
                "ko": "이상한 향기의 향로. 지니게 한 포켓몬은 여느 때보다 행동이 느려진다.",
                "en": "An item to be held by a Pokémon. This exotic-smelling incense makes the holder bloated and slow moving.",
                "ja": "ふしぎな　かおりの　おこう。　もたせた　ポケモンは　いつもより　こうどうが　おそくなる。",
                "es": "Incienso de exótico aroma que hace que el Pokémon que lo lleve esté aturdido y se mueva más despacio.",
                "fr": "Objet à tenir. Un encens au parfum exotique qui fait enfler son porteur et le fait se déplacer lentement.",
                "de": "Ein Item zum Tragen. Dieses exotische Duftkraut macht den Träger benommen und langsam.",
            ]),
        "ganlon-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "용아열매", "en": "Ganlon Berry", "ja": "リュガのみ", "es": "Baya Gonlan", "fr": "Baie Lingan", "de": "Linganbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 자신의 방어가 올라간다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, its Defense stat will increase when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　じぶんの　ぼうぎょが　あがる。",
                "es": "Si la lleva un Pokémon, le sube la Defensa en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente la Défense en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere den Verteidigungs-Wert eines Pokémon, sobald es in einer Notlage steckt.",
            ]),
        "ghost-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "고스트주얼", "en": "Ghost Gem", "ja": "ゴーストジュエル", "es": "Gema Fantasma", "fr": "Joyau Spectre", "de": "Geisterjuwel"],
            texts: [
                "ko": "고스트타입의 주얼. 지니게 하면 한 번만 고스트 기술의 위력이 강해진다.",
                "en": "A gem with a spectral essence. When held, it strengthens the power of a Ghost-type move one time.",
                "ja": "ゴーストの　タイプの　ジュエル。　もたせると　いちどだけ　ゴーストの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Fantasma. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Spectre.",
                "de": "Ein Juwel vom Typ Geist. Es erhöht einmalig die Stärke einer Attacke vom Typ Geist.",
            ]),
        "ghost-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "고스트메모리", "en": "Ghost Memory", "ja": "ゴーストメモリ", "es": "Disco Fantasma", "fr": "ROM Spectre", "de": "Geister-Disc"],
            texts: [
                "ko": "고스트타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Ghost-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "ゴーストタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Fantasma. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Spectre. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Geist. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "grass-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "풀주얼", "en": "Grass Gem", "ja": "くさのジュエル", "es": "Gema Planta", "fr": "Joyau Plante", "de": "Pflanzenjuwel"],
            texts: [
                "ko": "풀타입의 주얼. 지니게 하면 한 번만 풀 기술의 위력이 강해진다.",
                "en": "A gem with an essence of nature. When held, it strengthens the power of a Grass-type move one time.",
                "ja": "くさの　タイプの　ジュエル。　もたせると　いちどだけ　くさの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Planta. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Plante.",
                "de": "Ein Juwel vom Typ Pflanze. Es erhöht einmalig die Stärke einer Attacke vom Typ Pflanze.",
            ]),
        "grass-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "그래스메모리", "en": "Grass Memory", "ja": "グラスメモリ", "es": "Disco Planta", "fr": "ROM Plante", "de": "Pflanzen-Disc"],
            texts: [
                "ko": "풀타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Grass-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "くさタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Planta. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Plante. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Pflanze. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "grassy-seed": Entry(appOriginalLanguages: [],
            names: ["ko": "그래스시드", "en": "Grassy Seed", "ja": "グラスシード", "es": "Semilla Hierba", "fr": "Graine Herbe", "de": "Gras-Samen"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 그래스필드일 때 사용하여 방어가 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Defense on Grassy Terrain. It can only be used once.",
                "ja": "ポケモンに　もたせると　グラスフィールドのときに　つかって　ぼうぎょが　あがる。",
                "es": "Aumenta la Defensa del portador si se usa cuando el terreno está cubierto por un campo de hierba.",
                "fr": "Objet à tenir. Augmente la Défense lorsque le terrain est couvert d’un Champ Herbu.",
                "de": "Gibst du den Samen einem Pokémon zum Tragen, setzt es ihn ein, wenn ein Grasfeld aktiv ist, und erhöht dadurch seine Verteidigung.",
            ]),
        "grip-claw": Entry(appOriginalLanguages: [],
            names: ["ko": "끈기갈고리손톱", "en": "Grip Claw", "ja": "ねばりのかぎづめ", "es": "Garra Garfio", "fr": "Accro Griffe", "de": "Griffklaue"],
            texts: [
                "ko": "지니게 하면 조이기나 김밥말이 등 데미지를 계속 주는 기술의 턴 수가 늘어난다.",
                "en": "An item to be held by a Pokémon. It extends the duration of multi-turn attacks, such as Bind and Wrap.",
                "ja": "もたせると　しめつける　まきつくなど　ダメージを　あたえつづける　わざの　ターンすうが　ふえる。",
                "es": "Prolonga la duración de ataques multiturno como Atadura y Constricción si la lleva un Pokémon.",
                "fr": "Objet à tenir. Prolonge la durée des attaques à tours multiples telles que Ligotage et Étreinte.",
                "de": "Ein Item zum Tragen. Verlängert die Dauer von Klammergriff, Wickel etc.",
            ]),
        "griseous-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "백금옥", "en": "Griseous Orb", "ja": "はっきんだま", "es": "Griseosfera", "fr": "Orbe Platiné", "de": "Platinum-Orb"],
            texts: [
                "ko": "기라티나에게 지니게 하면 드래곤과 고스트타입 기술의 위력이 올라가는 반짝반짝 빛나는 구슬.",
                "en": "A glowing orb to be held by Giratina. It boosts the power of Dragon- and Ghost-type moves when it is held.",
                "ja": "ギラティナに　もたせると　ドラゴンと　ゴーストタイプの　わざの　いりょくが　あがる　ひかり　かがやく　たま。",
                "es": "Una esfera brillante que potencia los movimientos de tipo Dragón y Fantasma. Debe llevarla Giratina.",
                "fr": "Un mystérieux objet destiné à Giratina. Améliore les capacités de types Dragon et Spectre.",
                "de": "Ein glühender Orb. Verstärkt Attacken vom Typ Drache und Geist, wenn Giratina ihn trägt.",
            ]),
        "ground-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "땅주얼", "en": "Ground Gem", "ja": "じめんのジュエル", "es": "Gema Tierra", "fr": "Joyau Sol", "de": "Bodenjuwel"],
            texts: [
                "ko": "땅타입의 주얼. 지니게 하면 한 번만 땅 기술의 위력이 강해진다.",
                "en": "A gem with an essence of land. When held, it strengthens the power of a Ground-type move one time.",
                "ja": "じめんの　タイプの　ジュエル。　もたせると　いちどだけ　じめんの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Tierra. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Sol.",
                "de": "Ein Juwel vom Typ Boden. Es erhöht einmalig die Stärke einer Attacke vom Typ Boden.",
            ]),
        "ground-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "그라운드메모리", "en": "Ground Memory", "ja": "グラウンドメモリ", "es": "Disco Tierra", "fr": "ROM Sol", "de": "Boden-Disc"],
            texts: [
                "ko": "땅타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Ground-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "じめんタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Tierra. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Sol. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Boden. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "heavy-duty-boots": Entry(appOriginalLanguages: [],
            names: ["ko": "통굽부츠", "en": "Heavy-Duty Boots", "ja": "あつぞこブーツ", "es": "Botas Gruesas", "fr": "Grosses Bottes", "de": "Plateauschuhe"],
            texts: [
                "ko": "발밑에 설치된 함정 등의 영향을 받지 않게 된다.",
                "en": "These boots prevent the effects of traps set on the battlefield.",
                "ja": "あしばに　しかけられた　わななどの　えいきょうを　うけなくなる。",
                "es": "Anula los efectos de aquello que se coloca a los pies del Pokémon para obstaculizarlo, como las trampas.",
                "fr": "Le porteur ne subit plus les effets des pièges ou autres entraves posés sur le terrain.",
                "de": "Der Träger wird nicht mehr durch Fallen und andere Objekte beeinträchtigt, die auf dem Boden liegen.",
            ]),
        "iapapa-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "파야열매", "en": "Iapapa Berry", "ja": "イアのみ", "es": "Baya Pabaya", "fr": "Baie Papaya", "de": "Yapabeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 HP를 회복한다. 싫어하는 맛이면 혼란에 빠진다.",
                "en": "If held by a Pokémon, it restores the user’s HP in a pinch, but it will cause confusion if the user hates the taste.",
                "ja": "ポケモンに　もたせると　ピンチのとき　ＨＰを　かいふくする。　きらいな　あじだと　こんらん　する。",
                "es": "Los Pokémon pueden llevarla o usarla para restaurar algunos PS. Su sabor puede causar confusión si no les gusta.",
                "fr": "Tenue, cette Baie restaure des PV en cas de besoin, mais rend le Pokémon confus si son goût lui déplaît.",
                "de": "Als getragenes Item füllt die Beere im Notfall die KP eines Pokémon auf, doch ihr Aroma verwirrt jene, die es nicht mögen.",
            ]),
        "ice-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "얼음주얼", "en": "Ice Gem", "ja": "こおりのジュエル", "es": "Gema Hielo", "fr": "Joyau Glace", "de": "Eisjuwel"],
            texts: [
                "ko": "얼음타입의 주얼. 지니게 하면 한 번만 얼음 기술의 위력이 강해진다.",
                "en": "A gem with an essence of ice. When held, it strengthens the power of an Ice-type move one time.",
                "ja": "こおりの　タイプの　ジュエル。　もたせると　いちどだけ　こおりの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Hielo. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Glace.",
                "de": "Ein Juwel vom Typ Eis. Es erhöht einmalig die Stärke einer Attacke vom Typ Eis.",
            ]),
        "ice-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "아이스메모리", "en": "Ice Memory", "ja": "アイスメモリ", "es": "Disco Hielo", "fr": "ROM Glace", "de": "Eis-Disc"],
            texts: [
                "ko": "얼음타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Ice-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "こおりタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Hielo. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Glace. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Eis. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "iron-ball": Entry(appOriginalLanguages: [],
            names: ["ko": "검은철구", "en": "Iron Ball", "ja": "くろいてっきゅう", "es": "Bola Férrea", "fr": "Balle Fer", "de": "Eisenkugel"],
            texts: [
                "ko": "지니게 하면 스피드가 떨어진다. 비행타입이나 부유포켓몬은 땅 기술에 맞아 버린다.",
                "en": "An item to be held by a Pokémon. It lowers Speed and allows Ground-type moves to hit Flying types and holders that are levitating.",
                "ja": "もたせると　すばやさが　さがる。　ひこうタイプや　ふゆう　ポケモンは　じめんわざが　あたって　しまう。",
                "es": "Reduce la Velocidad. Los Pokémon que levitan y los de tipo Volador se tornan sensibles a movimientos de tipo Tierra.",
                "fr": "Objet à tenir. Réduit la Vitesse. Rend les porteurs de type Vol, ainsi que ceux en lévitation, sensibles aux capacités de type Sol.",
                "de": "Ein Item zum Tragen. Macht Pokémon des Typs Flug oder mit der Fähigkeit Schwebe anfällig für Boden-Attacken. Senkt den Initiative-Wert.",
            ]),
        "jaboca-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "자보열매", "en": "Jaboca Berry", "ja": "ジャポのみ", "es": "Baya Jaboca", "fr": "Baie Jaboca", "de": "Jabocabeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 물리 기술을 당했을 때 상대에게도 데미지를 준다.",
                "en": "A Berry to be consumed by Pokémon. If a physical attack hits the Pokémon holding it, the attacker will also be hurt.",
                "ja": "ポケモンに　もたせると　ぶつりわざを　うけたとき　あいてにも　ダメージを　あたえる。",
                "es": "Si la lleva un Pokémon cuando otro lanza un ataque físico, este último también recibe daño.",
                "fr": "Tenue, cette Baie inflige des dégâts à l’attaquant s’il utilise une capacité physique qui atteint sa cible.",
                "de": "Als getragenes Item bewirkt diese Beere Schaden bei jenen, die den Träger mit einer physischen Attacke treffen.",
            ]),
        "kee-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "악키열매", "en": "Kee Berry", "ja": "アッキのみ", "es": "Baya Biglia", "fr": "Baie Éka", "de": "Akibeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 물리 기술을 당했을 때 자신의 방어가 올라간다.",
                "en": "If held by a Pokémon, this Berry will increase the holder’s Defense if it’s hit with a physical move.",
                "ja": "ポケモンに　もたせると　ぶつりわざを　うけたとき　じぶんの　ぼうぎょが　あがる。",
                "es": "Si la lleva un Pokémon, aumenta su Defensa tras recibir un ataque físico.",
                "fr": "Tenue, cette Baie augmente la Défense du Pokémon lorsqu’il est touché par une capacité physique.",
                "de": "Als getragenes Item erhöht diese Beere die Verteidigung des Trägers, wenn dieser von physischen Attacken getroffen wird.",
            ]),
        "lagging-tail": Entry(appOriginalLanguages: [],
            names: ["ko": "느림보꼬리", "en": "Lagging Tail", "ja": "こうこうのしっぽ", "es": "Cola Plúmbea", "fr": "Ralentiqueue", "de": "Schwerschweif"],
            texts: [
                "ko": "매우 무거운 무언가의 꼬리. 지니게 하면 여느 때보다 행동이 느려진다.",
                "en": "An item to be held by a Pokémon. It is tremendously heavy and makes the holder move slower than usual.",
                "ja": "とても　おもたい　なにかの　しっぽ。　もたせると　いつもより　こうどうが　おそくなる。",
                "es": "Es muy pesada y hace que el Pokémon que la lleva se mueva más lento de lo normal.",
                "fr": "Objet à tenir extrêmement lourd qui ralentit le porteur.",
                "de": "Ein Item zum Tragen. Es ist immens schwer und senkt die Geschwindigkeit des Trägers.",
            ]),
        "lansat-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "랑사열매", "en": "Lansat Berry", "ja": "サンのみ", "es": "Baya Zonlan", "fr": "Baie Lansat", "de": "Lansatbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 공격이 급소를 맞히기 쉬워진다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, its critical-hit ratio will increase when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　こうげきが　きゅうしょに　あたりやすくなる。",
                "es": "Si la lleva un Pokémon, aumenta la probabilidad de dar un golpe crítico en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente le taux de critiques en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere die Volltrefferquote eines Pokémon, sobald es in einer Notlage steckt.",
            ]),
        "lax-incense": Entry(appOriginalLanguages: [],
            names: ["ko": "무사태평향로", "en": "Lax Incense", "ja": "のんきのおこう", "es": "Incienso Suave", "fr": "Encens Doux", "de": "Laxrauch"],
            texts: [
                "ko": "지니게 하면 향로의 이상한 향기가 상대를 혼란시켜 기술이 명중하기 어려워진다.",
                "en": "An item to be held by a Pokémon. The beguiling aroma of this incense may cause attacks to miss its holder.",
                "ja": "もたせると　おこうの　ふしぎな　かおりが　あいてを　まどわせて　わざが　めいちゅう　しにくくなる。",
                "es": "Debe llevarlo un Pokémon. Su peculiar aroma reduce la Precisión del objetivo.",
                "fr": "Objet à tenir. Le parfum trompeur de cet encens baisse la Précision de l’ennemi.",
                "de": "Ein Item zum Tragen. Das verwirrende Aroma senkt die Genauigkeit des Gegners.",
            ]),
        "leppa-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "과사열매", "en": "Leppa Berry", "ja": "ヒメリのみ", "es": "Baya Zanama", "fr": "Baie Mepo", "de": "Jonagobeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 PP를 10만큼 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can restore 10 PP to a depleted move during battle.",
                "ja": "ポケモンに　もたせると　ＰＰを　１０だけ　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para restaurar 10 PP de un movimiento.",
                "fr": "Une Baie qui restaure 10 PP lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, füllt sie die AP einer Attacke um 10 Punkte auf.",
            ]),
        "liechi-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "치리열매", "en": "Liechi Berry", "ja": "チイラのみ", "es": "Baya Lichi", "fr": "Baie Lichii", "de": "Lydzibeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 자신의 공격이 올라간다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, its Attack stat will increase when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　じぶんの　こうげきが　あがる。",
                "es": "Si la lleva un Pokémon, le sube el Ataque en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente l’Attaque en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere den Angriffs-Wert eines Pokémon, sobald es in einer Notlage steckt.",
            ]),
        "light-ball": Entry(appOriginalLanguages: [],
            names: ["ko": "전기구슬", "en": "Light Ball", "ja": "でんきだま", "es": "Bola Luminosa", "fr": "Balle Lumière", "de": "Kugelblitz"],
            texts: [
                "ko": "피카츄에게 지니게 하면 공격과 특수공격의 위력이 올라가는 이상한 구슬.",
                "en": "An item to be held by Pikachu. It’s a puzzling orb that boosts its Attack and Sp. Atk stats.",
                "ja": "ピカチュウに　もたせると　こうげきと　とくこうの　いりょくが　あがる　ふしぎな　たま。",
                "es": "Asombrosa esfera que debe llevar Pikachu y que aumenta su Ataque y su Ataque Especial.",
                "fr": "Objet à faire tenir à Pikachu. Un orbe énigmatique qui augmente son Attaque et son Attaque Spéciale.",
                "de": "Ein Item, das von Pikachu getragen werden kann. Es erhöht den Angriffs-Wert und Spezial-Angriffs-Wert.",
            ]),
        "light-clay": Entry(appOriginalLanguages: [],
            names: ["ko": "빛의점토", "en": "Light Clay", "ja": "ひかりのねんど", "es": "Refleluz", "fr": "Lumargile", "de": "Lichtlehm"],
            texts: [
                "ko": "지니게 한 포켓몬이 빛의장막이나 리플렉터를 사용했을 때 여느 때보다 긴 시간 동안 지속된다.",
                "en": "An item to be held by a Pokémon. Protective moves like Light Screen and Reflect will be effective longer.",
                "ja": "もたせた　ポケモンが　ひかりのかべや　リフレクターを　つかったとき　いつもよりも　ながく　のこる。",
                "es": "Prolonga la duración de barreras como las creadas por Reflejo y Pantalla de Luz. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Prolonge la durée des capacités barrières telles que Mur Lumière et Protection.",
                "de": "Ein Item zum Tragen. Verlängert die Dauer von Lichtschild, Reflektor etc.",
            ]),
        "loaded-dice": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "속임수주사위", "en": "Loaded Dice", "ja": "いかさまダイス", "es": "Dado Trucado", "fr": "Dé Pipé", "de": "Gezinkter Würfel"],
            texts: [
                "ko": "무게가 쏠린 주사위. 지니게 하면 여러 번 맞히는 기술이 많은 횟수로 맞는다.",
                "en": "Weighted dice that always roll high. Moves that hit several times hit more often.",
                "ja": "おもりの　はいった　サイコロ。　もたせると　れんぞくで　あたる　わざが　おおくの　かいすう　あたる。",
                "es": "Unos dados trucados. Los movimientos de golpes múltiples del portador aciertan más veces.",
                "fr": "Des dés pipés. Les capacités à coups multiples du porteur frappent plus de fois.",
                "pt": "Dados viciados. Os golpes de múltiplos acertos do portador acertam mais vezes.",
                "de": "Gezinkte Würfel. Mehrfachtreffer-Attacken des Trägers treffen öfter.",
                "ru": "Утяжелённые кости. Многоударные атаки носителя бьют чаще.",
            ]),
        "lucky-punch": Entry(appOriginalLanguages: [],
            names: ["ko": "럭키펀치", "en": "Lucky Punch", "ja": "ラッキーパンチ", "es": "Puño Suerte", "fr": "Poing Chance", "de": "Lucky Punch"],
            texts: [
                "ko": "행운을 부르는 글러브다. 럭키에게 지니게 하면 기술이 급소에 맞기 쉬워진다.",
                "en": "An item to be held by Chansey. This pair of lucky boxing gloves will boost Chansey’s critical-hit ratio.",
                "ja": "こううんを　よぶ　グローブ。　ラッキーに　もたせると　わざが　きゅうしょに　あたりやすくなる。",
                "es": "Un par de guantes que debe llevar Chansey. Potencian mucho su índice de golpe crítico.",
                "fr": "Objet à faire tenir à Leveinard. Une paire de gants qui augmente son taux de critiques.",
                "de": "Ein Item, das von Chaneira getragen werden kann. Diese Handschuhe erhöhen die Volltrefferquote des Trägers.",
            ]),
        "luminous-moss": Entry(appOriginalLanguages: [],
            names: ["ko": "빛이끼", "en": "Luminous Moss", "ja": "ひかりごけ", "es": "Musgo Brillante", "fr": "Lichen Lumineux", "de": "Leuchtmoos"],
            texts: [
                "ko": "단 한 번 쓰면 없어지는 빛이끼. 지니게 하고 물 기술을 받으면 특수방어가 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Sp. Def if the holder is hit with a Water-type attack. It can only be used once.",
                "ja": "つかいすての　ひかりごけ。　もたせて　みずの　わざを　うけると　とくぼうが　あがる。",
                "es": "Objeto de un solo uso. Aumenta la Defensa Especial del Pokémon que lo lleva si este recibe un ataque de tipo Agua.",
                "fr": "Objet à tenir. Du lichen à usage unique qui augmente la Défense Spéciale du porteur lorsqu’il encaisse une attaque de type Eau.",
                "de": "Wird der Träger von einer Wasser-Attacke getroffen, steigt seine Spezial-Verteidigung und das Item verschwindet.",
            ]),
        "lustrous-orb": Entry(appOriginalLanguages: [],
            names: ["ko": "백옥", "en": "Lustrous Orb", "ja": "しらたま", "es": "Lustresfera", "fr": "Orbe Perlé", "de": "Weiß-Orb"],
            texts: [
                "ko": "펄기아에게 지니게 하면 드래곤과 물타입 기술의 위력이 올라가는 아름답게 반짝이는 구슬.",
                "en": "A beautifully glowing orb to be held by Palkia. It boosts the power of Dragon- and Water-type moves when it is held.",
                "ja": "パルキアに　もたせると　ドラゴンと　みずタイプの　わざの　いりょくが　あがる　うつくしく　かがやく　たま。",
                "es": "Una bonita esfera que potencia los movimientos de tipo Dragón y Agua. Debe llevarla Palkia.",
                "fr": "Un bel orbe luisant destiné à Palkia. Augmente la puissance des capacités de types Dragon et Eau.",
                "de": "Ein hell leuchtender Orb. Verstärkt Attacken vom Typ Drache und Wasser, wenn Palkia ihn trägt.",
            ]),
        "macho-brace": Entry(appOriginalLanguages: [],
            names: ["ko": "교정깁스", "en": "Macho Brace", "ja": "きょうせいギプス", "es": "Brazal Firme", "fr": "Bracelet Macho", "de": "Machoschiene"],
            texts: [
                "ko": "단단하고 무거운 깁스. 지니게 하면 스피드는 떨어지지만 여느 때보다 강하게 키우기 쉽다.",
                "en": "An item to be held by a Pokémon. This stiff, heavy brace helps Pokémon grow strong but cuts Speed in battle.",
                "ja": "かたくて　おもい　ギプス。　もたせると　すばやさは　さがるが　ふつうより　つよく　そだちやすい。",
                "es": "Sólido y pesado brazal que potencia aún más las características del Pokémon que lo lleva al subir de nivel, pero que reduce la Velocidad en combate.",
                "fr": "Objet à tenir. Un bracelet dur et lourd qui rend le porteur plus fort, mais baisse sa Vitesse.",
                "de": "Ein Item, das ein Pokémon tragen kann. Der Initiative-Wert sinkt zwar, aber es wird dafür umso stärker.",
            ]),
        "mago-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "마고열매", "en": "Mago Berry", "ja": "マゴのみ", "es": "Baya Ango", "fr": "Baie Mago", "de": "Magobeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 HP를 회복한다. 싫어하는 맛이면 혼란에 빠진다.",
                "en": "If held by a Pokémon, it restores the user’s HP in a pinch, but it will cause confusion if the user hates the taste.",
                "ja": "ポケモンに　もたせると　ピンチのとき　ＨＰを　かいふくする。　きらいな　あじだと　こんらん　する。",
                "es": "Los Pokémon pueden llevarla o usarla para restaurar algunos PS. Su sabor puede causar confusión si no les gusta.",
                "fr": "Tenue, cette Baie restaure des PV en cas de besoin, mais rend le Pokémon confus si son goût lui déplaît.",
                "de": "Als getragenes Item füllt die Beere im Notfall die KP eines Pokémon auf, doch ihr Aroma verwirrt jene, die es nicht mögen.",
            ]),
        "maranga-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "타라프열매", "en": "Maranga Berry", "ja": "タラプのみ", "es": "Baya Maranga", "fr": "Baie Rangma", "de": "Tarabeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 특수 기술을 당했을 때 자신의 특수방어가 올라간다.",
                "en": "If held by a Pokémon, this Berry will increase the holder’s Sp. Def if it’s hit with a special move.",
                "ja": "ポケモンに　もたせると　とくしゅわざを　うけたとき　じぶんの　とくぼうが　あがる。",
                "es": "Si la lleva un Pokémon, aumenta su Defensa Especial tras recibir un ataque especial.",
                "fr": "Tenue, cette Baie augmente la Défense Spéciale du Pokémon lorsqu’il est touché par une capacité spéciale.",
                "de": "Als getragenes Item erhöht diese Beere die Spezial-Verteidigung des Trägers, wenn dieser von Spezial-Attacken getroffen wird.",
            ]),
        "mental-herb": Entry(appOriginalLanguages: [],
            names: ["ko": "멘탈허브", "en": "Mental Herb", "ja": "メンタルハーブ", "es": "Hierba Mental", "fr": "Herbe Mental", "de": "Mentalkraut"],
            texts: [
                "ko": "지니게 한 포켓몬은 헤롱헤롱 상태가 되었을 때 한 번만 회복한다.",
                "en": "An item to be held by a Pokémon. The holder shakes off move-binding effects to move freely. It can be used only once.",
                "ja": "もたせた　ポケモンが　じゆうに　わざを　だせなくなったときに　いちどだけ　かいふくする。",
                "es": "El Pokémon que la lleva se libera del efecto de movimientos que restringen sus acciones. Solo puede usarse una vez.",
                "fr": "Objet à tenir. Guérit de certaines attaques limitant le choix des capacités. Ne peut être utilisé qu’une fois.",
                "de": "Ein Item, das von einem Pokémon getragen werden kann. Befreit den Träger einmalig von Effekten, die ihn vom Einsatz von Attacken abhalten.",
            ]),
        "metal-powder": Entry(appOriginalLanguages: [],
            names: ["ko": "금속파우더", "en": "Metal Powder", "ja": "メタルパウダー", "es": "Polvo Metálico", "fr": "Poudre Métal", "de": "Metallstaub"],
            texts: [
                "ko": "메타몽에게 지니게 하면 방어가 올라가는 이상한 가루. 매우 잘고 단단하다.",
                "en": "An item to be held by Ditto. Extremely fine yet hard, this odd powder boosts the Defense stat.",
                "ja": "メタモンに　もたせると　ぼうぎょが　あがる　ふしぎなこな。　とても　こまかくて　かたい。",
                "es": "Debe llevarlo Ditto. Es un polvo muy fino, pero a la vez poderoso, que aumenta su Defensa.",
                "fr": "Objet à faire tenir à Métamorph. Cette poudre étrange, très fine mais résistante, augmente sa Défense.",
                "de": "Ein Item, das Ditto zum Tragen gegeben werden kann. Fein und doch hart, erhöht es den Verteidigungs-Wert.",
            ]),
        "metronome": Entry(appOriginalLanguages: [],
            names: ["ko": "메트로놈", "en": "Metronome", "ja": "メトロノーム", "es": "Metrónomo", "fr": "Métronome", "de": "Metronom"],
            texts: [
                "ko": "지니게 하면 똑같은 기술을 연속으로 사용했을 때 위력이 올라간다. 그만두면 위력이 되돌아간다.",
                "en": "An item to be held by a Pokémon. It boosts moves used consecutively but only until a different move is used.",
                "ja": "もたせると　おなじわざを　れんぞくで　つかったとき　いりょくが　あがる。　やめると　いりょくは　もどる。",
                "es": "Potencia un movimiento que se use de forma consecutiva. Pero el efecto se pierde si se emplea otro movimiento.",
                "fr": "Objet à tenir. Booste une capacité utilisée à répétition. L’effet s’annule si une autre capacité est utilisée.",
                "de": "Ein Item zum Tragen. Verstärkt eine Attacke, je öfter sie in Folge ausgeführt wird.",
            ]),
        "micle-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "미클열매", "en": "Micle Berry", "ja": "ミクルのみ", "es": "Baya Lagro", "fr": "Baie Micle", "de": "Wunfrubeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 한 번만 기술의 명중률이 올라간다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, its accuracy will increase just once when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　いちどだけ　わざの　めいちゅうりつが　あがる。",
                "es": "Cuando la lleva un Pokémon, le sube la precisión de un movimiento en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente une fois la Précision d’une capacité en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere die Genauigkeit eines Pokémon, sobald es in einer Notlage steckt.",
            ]),
        "misty-seed": Entry(appOriginalLanguages: [],
            names: ["ko": "미스트시드", "en": "Misty Seed", "ja": "ミストシード", "es": "Semilla Bruma", "fr": "Graine Brume", "de": "Nebel-Samen"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 미스트필드일 때 사용하여 특수방어가 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Sp. Def on Misty Terrain. It can only be used once.",
                "ja": "ポケモンに　もたせると　ミストフィールドのときに　つかって　とくぼうが　あがる。",
                "es": "Aumenta la Defensa Especial del portador si se usa cuando el terreno está cubierto por un campo de niebla.",
                "fr": "Objet à tenir. Augmente la Défense Spéciale lorsque le terrain est couvert d’un Champ Brumeux.",
                "de": "Gibst du den Samen einem Pokémon zum Tragen, setzt es ihn ein, wenn ein Nebelfeld aktiv ist, und erhöht dadurch seine Spezial-Verteidigung.",
            ]),
        "normal-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "노말주얼", "en": "Normal Gem", "ja": "ノーマルジュエル", "es": "Gema Normal", "fr": "Joyau Normal", "de": "Normaljuwel"],
            texts: [
                "ko": "노말타입의 주얼. 지니게 하면 한 번만 노말 기술의 위력이 강해진다.",
                "en": "A gem with an ordinary essence. When held, it strengthens the power of a Normal-type move one time.",
                "ja": "ノーマルの　タイプの　ジュエル。　もたせると　いちどだけ　ノーマルの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Normal. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Normal.",
                "de": "Ein Juwel vom Typ Normal. Es erhöht einmalig die Stärke einer Attacke vom Typ Normal.",
            ]),
        "odd-incense": Entry(appOriginalLanguages: [],
            names: ["ko": "괴상한향로", "en": "Odd Incense", "ja": "あやしいおこう", "es": "Incienso Raro", "fr": "Encens Bizarre", "de": "Schrägrauch"],
            texts: [
                "ko": "이상한 향기의 향로. 지니게 하면 에스퍼타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This exotic-smelling incense boosts the power of Psychic-type moves.",
                "ja": "ふしぎな　かおりの　おこう。　もたせると　エスパータイプの　わざの　いりょくが　あがる。",
                "es": "Incienso de exótico aroma que fortalece los movimientos de tipo Psíquico. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un encens au parfum exotique augmentant la puissance des capacités de type Psy.",
                "de": "Ein Item zum Tragen. Dieses exotische Duftkraut verstärkt Attacken vom Typ Psycho.",
            ]),
        "oran-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "오랭열매", "en": "Oran Berry", "ja": "オレンのみ", "es": "Baya Aranja", "fr": "Baie Oran", "de": "Sinelbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 HP를 10만큼 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can restore its own HP by 10 points during battle.",
                "ja": "ポケモンに　もたせると　ＨＰを　１０だけ　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para restaurar 10 PS.",
                "fr": "Une Baie qui restaure 10 PV lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, füllt sie seine KP um 10 Punkte auf.",
            ]),
        "pecha-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "복슝열매", "en": "Pecha Berry", "ja": "モモンのみ", "es": "Baya Meloc", "fr": "Baie Pêcha", "de": "Pirsifbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 독을 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can recover from poisoning on its own in battle.",
                "ja": "ポケモンに　もたせると　どくを　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para curarse del envenenamiento.",
                "fr": "Une Baie qui soigne l’empoisonnement lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, heilt diese es von Vergiftung.",
            ]),
        "persim-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "시몬열매", "en": "Persim Berry", "ja": "キーのみ", "es": "Baya Caquic", "fr": "Baie Kika", "de": "Persimbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 혼란을 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can recover from confusion on its own in battle.",
                "ja": "ポケモンに　もたせると　こんらんを　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para librarse de la confusión.",
                "fr": "Une Baie qui soigne la confusion lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, heilt diese es von Verwirrung.",
            ]),
        "petaya-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "야타비열매", "en": "Petaya Berry", "ja": "ヤタピのみ", "es": "Baya Yapati", "fr": "Baie Pitaye", "de": "Tahaybeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 자신의 특수공격이 올라간다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, its Sp. Atk stat will increase when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　じぶんの　とくこうが　あがる。",
                "es": "Si la lleva un Pokémon, le sube el Ataque Especial en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente l’Attaque Spéciale en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere den Spezial-Angriffs-Wert eines Pokémon, sobald es in einer Notlage steckt.",
            ]),
        "poison-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "독주얼", "en": "Poison Gem", "ja": "どくのジュエル", "es": "Gema Veneno", "fr": "Joyau Poison", "de": "Giftjuwel"],
            texts: [
                "ko": "독타입의 주얼. 지니게 하면 한 번만 독 기술의 위력이 강해진다.",
                "en": "A gem with an essence of poison. When held, it strengthens the power of a Poison-type move one time.",
                "ja": "どくの　タイプの　ジュエル。　もたせると　いちどだけ　どくの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Veneno. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Poison.",
                "de": "Ein Juwel vom Typ Gift. Es erhöht einmalig die Stärke einer Attacke vom Typ Gift.",
            ]),
        "poison-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "포이즌메모리", "en": "Poison Memory", "ja": "ポイズンメモリ", "es": "Disco Veneno", "fr": "ROM Poison", "de": "Gift-Disc"],
            texts: [
                "ko": "독타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Poison-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "どくタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Veneno. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Poison. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Gift. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "power-anklet": Entry(appOriginalLanguages: [],
            names: ["ko": "파워앵클릿", "en": "Power Anklet", "ja": "パワーアンクル", "es": "Franja Recia", "fr": "Chaîne Pouvoir", "de": "Machtkette"],
            texts: [
                "ko": "지니게 하면 스피드는 떨어지지만 여느 때보다 포켓몬의 스피드를 올리면서 키우기가 쉽다.",
                "en": "An item to be held by a Pokémon. It reduces Speed but allows the holder’s Speed stat to grow more after battling.",
                "ja": "もたせると　すばやさが　さがるが　ふつうよりも　ポケモンの　すばやさが　たかく　そだちやすい。",
                "es": "Potencia la Velocidad de base, pero reduce la Velocidad en combate. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Permet à la Vitesse de progresser plus vite, mais la réduit pendant le combat.",
                "de": "Ein Item zum Tragen. Erhöht nach dem Kampf den Initiative-Wert, senkt aber die Initiative allgemein.",
            ]),
        "power-band": Entry(appOriginalLanguages: [],
            names: ["ko": "파워밴드", "en": "Power Band", "ja": "パワーバンド", "es": "Banda Recia", "fr": "Bandeau Pouvoir", "de": "Machtband"],
            texts: [
                "ko": "지니게 하면 스피드는 떨어지지만 여느 때보다 포켓몬의 특수방어를 올리면서 키우기가 쉽다.",
                "en": "An item to be held by a Pokémon. It reduces Speed but allows the holder’s Sp. Def stat to grow more after battling.",
                "ja": "もたせると　すばやさが　さがるが　ふつうよりも　ポケモンの　とくぼうが　たかく　そだちやすい。",
                "es": "Potencia la Defensa Especial de base, pero reduce la Velocidad en combate. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Permet à la Défense Spéciale de progresser plus vite, mais réduit la Vitesse pendant le combat.",
                "de": "Ein Item zum Tragen. Erhöht nach dem Kampf den Spezial-Verteidigungs-Wert, senkt aber die Initiative.",
            ]),
        "power-belt": Entry(appOriginalLanguages: [],
            names: ["ko": "파워벨트", "en": "Power Belt", "ja": "パワーベルト", "es": "Cinto Recio", "fr": "Ceinture Pouvoir", "de": "Machtgurt"],
            texts: [
                "ko": "지니게 하면 스피드는 떨어지지만 여느 때보다 포켓몬의 방어를 올리면서 키우기가 쉽다.",
                "en": "An item to be held by a Pokémon. It reduces Speed but allows the holder’s Defense stat to grow more after battling.",
                "ja": "もたせると　すばやさが　さがるが　ふつうよりも　ポケモンの　ぼうぎょが　たかく　そだちやすい。",
                "es": "Potencia la Defensa de base, pero reduce la Velocidad en combate. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Permet à la Défense de progresser plus vite, mais réduit la Vitesse pendant le combat.",
                "de": "Ein Item zum Tragen. Erhöht nach dem Kampf den Verteidigungs-Wert, senkt aber die Initiative.",
            ]),
        "power-bracer": Entry(appOriginalLanguages: [],
            names: ["ko": "파워리스트", "en": "Power Bracer", "ja": "パワーリスト", "es": "Brazal Recio", "fr": "Poignet Pouvoir", "de": "Machtreif"],
            texts: [
                "ko": "지니게 하면 스피드는 떨어지지만 여느 때보다 포켓몬의 공격을 올리면서 키우기가 쉽다.",
                "en": "An item to be held by a Pokémon. It reduces Speed but allows the holder’s Attack stat to grow more after battling.",
                "ja": "もたせると　すばやさが　さがるが　ふつうよりも　ポケモンの　こうげきが　たかく　そだちやすい。",
                "es": "Potencia el Ataque de base, pero reduce la Velocidad en combate. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Permet à l’Attaque de progresser plus vite, mais réduit la Vitesse pendant le combat.",
                "de": "Ein Item zum Tragen. Erhöht nach dem Kampf den Angriffs-Wert, senkt aber die Initiative.",
            ]),
        "power-herb": Entry(appOriginalLanguages: [],
            names: ["ko": "파워풀허브", "en": "Power Herb", "ja": "パワフルハーブ", "es": "Hierba Única", "fr": "Herbe Pouvoir", "de": "Energiekraut"],
            texts: [
                "ko": "지니게 한 포켓몬은 한 번만 1턴째에 힘을 모으는 기술을 바로 사용할 수가 있다.",
                "en": "A single-use item to be held by a Pokémon. It allows the holder to immediately use a move that normally requires a turn to charge.",
                "ja": "もたせた　ポケモンは　いちどだけ　１ターンめに　ちからを　ためるわざを　すぐに　つかうことが　できる。",
                "es": "Permite el uso inmediato de cualquier movimiento en el primer turno. Es de un solo uso y debe llevarla un Pokémon.",
                "fr": "Objet à tenir et à usage unique. Permet d’utiliser immédiatement une capacité qui devrait se charger au premier tour.",
                "de": "Ein Item zum einmaligen Tragen. Der Träger kann dadurch eine Attacke sofort einsetzen, die sonst aufgeladen werden muss.",
            ]),
        "power-lens": Entry(appOriginalLanguages: [],
            names: ["ko": "파워렌즈", "en": "Power Lens", "ja": "パワーレンズ", "es": "Lente Recia", "fr": "Lentille Pouvoir", "de": "Machtlinse"],
            texts: [
                "ko": "지니게 하면 스피드는 떨어지지만 여느 때보다 포켓몬의 특수공격을 올리면서 키우기가 쉽다.",
                "en": "An item to be held by a Pokémon. It reduces Speed but allows the holder’s Sp. Atk stat to grow more after battling.",
                "ja": "もたせると　すばやさが　さがるが　ふつうよりも　ポケモンの　とくこうが　たかく　そだちやすい。",
                "es": "Potencia el Ataque Especial de base, pero reduce la Velocidad en combate. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Permet à l’Attaque Spéciale de progresser plus vite, mais réduit la Vitesse pendant le combat.",
                "de": "Ein Item zum Tragen. Erhöht nach dem Kampf den Spezial-Angriffs-Wert, senkt aber die Initiative.",
            ]),
        "power-weight": Entry(appOriginalLanguages: [],
            names: ["ko": "파워웨이트", "en": "Power Weight", "ja": "パワーウエイト", "es": "Pesa Recia", "fr": "Poids Pouvoir", "de": "Machtgewicht"],
            texts: [
                "ko": "지니게 하면 스피드는 떨어지지만 여느 때보다 포켓몬의 HP를 올리면서 키우기가 쉽다.",
                "en": "An item to be held by a Pokémon. It reduces Speed but allows the holder’s max HP to grow more after battling.",
                "ja": "もたせると　すばやさが　さがるが　ふつうよりも　ポケモンの　ＨＰが　たかく　そだちやすい。",
                "es": "Mejora los PS de base, pero reduce la Velocidad en combate. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Permet aux PV max de progresser plus vite, mais réduit la Vitesse pendant le combat.",
                "de": "Ein Item zum Tragen. Erhöht nach dem Kampf die maximalen KP, senkt aber die Initiative.",
            ]),
        "protective-pads": Entry(appOriginalLanguages: [],
            names: ["ko": "방호패드", "en": "Protective Pads", "ja": "ぼうごパット", "es": "Paracontacto", "fr": "Pare-Effet", "de": "Schutzpolster"],
            texts: [
                "ko": "공격하는 상대와 접촉해서 받게 되는 효과를 받지 않게 한다.",
                "en": "An item to be held by a Pokémon. These pads protect the holder from effects caused by making direct contact with the target.",
                "ja": "こうげき　する　あいてに　さわって　うける　こうかを　うけないように　する。",
                "es": "Protege al Pokémon de los efectos que le produciría el contacto directo en combate.",
                "fr": "Objet à tenir. Annule les effets subis par le porteur quand il utilise une attaque directe sur un autre Pokémon.",
                "de": "Greift der Träger ein Ziel an, ist er vor Effekten, die durch direkten Kontakt mit diesem ausgelöst werden, geschützt.",
            ]),
        "psychic-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "에스퍼주얼", "en": "Psychic Gem", "ja": "エスパージュエル", "es": "Gema Psíquica", "fr": "Joyau Psy", "de": "Psychojuwel"],
            texts: [
                "ko": "에스퍼타입의 주얼. 지니게 하면 한 번만 에스퍼 기술의 위력이 강해진다.",
                "en": "A gem with an essence of the mind. When held, it strengthens the power of a Psychic-type move one time.",
                "ja": "エスパーの　タイプの　ジュエル。　もたせると　いちどだけ　エスパーの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Psíquico. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Psy.",
                "de": "Ein Juwel vom Typ Psycho. Es erhöht einmalig die Stärke einer Attacke vom Typ Psycho.",
            ]),
        "psychic-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "사이킥메모리", "en": "Psychic Memory", "ja": "サイキックメモリ", "es": "Disco Psíquico", "fr": "ROM Psy", "de": "Psycho-Disc"],
            texts: [
                "ko": "에스퍼타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Psychic-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "エスパータイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Psíquico. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Psy. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Psycho. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "psychic-seed": Entry(appOriginalLanguages: [],
            names: ["ko": "사이코시드", "en": "Psychic Seed", "ja": "サイコシード", "es": "Semilla Psique", "fr": "Graine Psychique", "de": "Psycho-Samen"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 사이코필드일 때 사용하여 특수방어가 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Sp. Def on Psychic Terrain. It can only be used once.",
                "ja": "ポケモンに　もたせると　サイコフィールドのときに　つかって　とくぼうが　あがる。",
                "es": "Aumenta la Defensa Especial del portador si se usa cuando el terreno está cubierto por un campo psíquico.",
                "fr": "Objet à tenir. Augmente la Défense Spéciale lorsque le terrain est couvert d’un Champ Psychique.",
                "de": "Gibst du den Samen einem Pokémon zum Tragen, setzt es ihn ein, wenn ein Psychofeld aktiv ist, und erhöht dadurch seine Spezial-Verteidigung.",
            ]),
        "quick-powder": Entry(appOriginalLanguages: [],
            names: ["ko": "스피드파우더", "en": "Quick Powder", "ja": "スピードパウダー", "es": "Polvo Veloz", "fr": "Poudre Vite", "de": "Flottstaub"],
            texts: [
                "ko": "메타몽에게 지니게 하면 스피드가 올라가는 이상한 가루. 매우 잘고 단단하다.",
                "en": "An item to be held by Ditto. Extremely fine yet hard, this odd powder boosts the Speed stat.",
                "ja": "メタモンに　もたせると　すばやさが　あがる　ふしぎなこな。　とても　こまかくて　かたい。",
                "es": "Debe llevarlo Ditto. Es un polvo muy fino, pero a la vez poderoso, que aumenta su Velocidad.",
                "fr": "Objet à faire tenir à Métamorph. Cette poudre étrange, très fine mais résistante, augmente sa Vitesse.",
                "de": "Ein Item, das Ditto zum Tragen gegeben werden kann. Fein und doch hart, erhöht es den Initiative-Wert.",
            ]),
        "rawst-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "복분열매", "en": "Rawst Berry", "ja": "チーゴのみ", "es": "Baya Safre", "fr": "Baie Fraive", "de": "Fragiabeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 화상을 회복한다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, it can recover from a burn on its own in battle.",
                "ja": "ポケモンに　もたせると　やけどを　かいふくする。",
                "es": "Los Pokémon pueden llevarla o usarla para curarse las quemaduras.",
                "fr": "Une Baie qui soigne une brûlure lorsqu’elle est tenue par un Pokémon.",
                "de": "Gibst du die Beere einem Pokémon zum Tragen, heilt diese es von Verbrennungen.",
            ]),
        "ring-target": Entry(appOriginalLanguages: [],
            names: ["ko": "겨냥표적", "en": "Ring Target", "ja": "ねらいのまと", "es": "Blanco", "fr": "Point de Mire", "de": "Zielscheibe"],
            texts: [
                "ko": "포켓몬 타입의 상성 때문에 무효였던 기술이 맞게 되어 버린다.",
                "en": "An item to be held by a Pokémon. Moves that normally have no effect will land on a Pokémon holding it.",
                "ja": "ポケモンの　タイプの　あいしょうで　むこう　だった　わざが　あたるように　なってしまう。",
                "es": "El Pokémon que lo lleva es vulnerable frente a movimientos que normalmente no afectan a su tipo.",
                "fr": "Objet à tenir. Rend le porteur sensible aux capacités auxquelles il devrait être immunisé en raison de son type.",
                "de": "Attacken, die aufgrund der Wechselwirkungen zwischen den Typen keine Wirkung haben, treffen den Träger.",
            ]),
        "rock-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "바위주얼", "en": "Rock Gem", "ja": "いわのジュエル", "es": "Gema Roca", "fr": "Joyau Roche", "de": "Gesteinsjuwel"],
            texts: [
