                "es": "Incienso de exótico aroma que fortalece los movimientos de tipo Planta. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un encens au parfum exotique augmentant la puissance des capacités de type Plante.",
                "de": "Ein Item zum Tragen. Dieses exotische Duftkraut verstärkt Attacken vom Typ Pflanze.",
            ]),
        "rowap-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "애터열매", "en": "Rowap Berry", "ja": "レンブのみ", "es": "Baya Magua", "fr": "Baie Pommo", "de": "Roselbeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 특수 기술을 당했을 때 상대에게도 데미지를 준다.",
                "en": "A Berry to be consumed by Pokémon. If a special attack hits the Pokémon holding it, the attacker will also be hurt.",
                "ja": "ポケモンに　もたせると　とくしゅわざを　うけたとき　あいてにも　ダメージを　あたえる。",
                "es": "Si la lleva un Pokémon cuando otro lanza un ataque especial, este último también recibe daño.",
                "fr": "Tenue, cette Baie inflige des dégâts à l’attaquant s’il utilise une capacité spéciale qui atteint sa cible.",
                "de": "Als getragenes Item bewirkt diese Beere Schaden bei jenen, die den Träger mit einer Spezial-Attacke treffen.",
            ]),
        "safety-goggles": Entry(appOriginalLanguages: [],
            names: ["ko": "방진고글", "en": "Safety Goggles", "ja": "ぼうじんゴーグル", "es": "Gafa Protectora", "fr": "Lunettes Filtre", "de": "Schutzbrille"],
            texts: [
                "ko": "날씨로 인한 데미지뿐만 아니라 가루를 내보내는 기술의 효과도 막을 수 있는 고글.",
                "en": "An item to be held by a Pokémon. These goggles protect the holder from both weather-related damage and powder.",
                "ja": "てんこうの　ダメージだけでなく　こなを　だす　わざの　こうかも　ふせげる　ゴーグル。",
                "es": "Gafa que protege de los efectos adversos del clima y del polvo lanzado por los rivales.",
                "fr": "Objet à tenir. Protège le Pokémon contre les dégâts dus à la météo et la plupart des capacités utilisant de la poudre.",
                "de": "Diese Brille schützt ihren Träger nicht nur vor wetterbedingtem Schaden, sondern auch vor vielen Attacken, bei denen Puder eingesetzt wird.",
            ]),
        "salac-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "캄라열매", "en": "Salac Berry", "ja": "カムラのみ", "es": "Baya Aslac", "fr": "Baie Sailak", "de": "Salkabeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 자신의 스피드가 올라간다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, its Speed stat will increase when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　じぶんの　すばやさが　あがる。",
                "es": "Si la lleva un Pokémon, le sube la Velocidad en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente la Vitesse en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere den Initiative-Wert eines Pokémon, sobald es in einer Notlage steckt.",
            ]),
        "sea-incense": Entry(appOriginalLanguages: [],
            names: ["ko": "바닷물향로", "en": "Sea Incense", "ja": "うしおのおこう", "es": "Incienso Marino", "fr": "Encens Mer", "de": "Seerauch"],
            texts: [
                "ko": "이상한 향기의 향로. 지니게 하면 물타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This incense has a curious aroma that boosts the power of Water-type moves.",
                "ja": "ふしぎな　かおりの　おこう。　もたせると　みずタイプの　わざの　いりょくが　あがる。",
                "es": "Tiene un curioso aroma que potencia los movimientos de tipo Agua. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un encens au parfum curieux augmentant la puissance des capacités de type Eau.",
                "de": "Ein Item zum Tragen. Dieses exotische Duftkraut verstärkt Attacken vom Typ Wasser.",
            ]),
        "shock-drive": Entry(appOriginalLanguages: [],
            names: ["ko": "번개카세트", "en": "Shock Drive", "ja": "イナズマカセット", "es": "FulgoROM", "fr": "Module Choc", "de": "Blitzmodul"],
            texts: [
                "ko": "게노세크트에게 지니게 하면 테크노버스터라는 기술이 전기타입으로 바뀌는 카세트.",
                "en": "A cassette to be held by Genesect. It changes Genesect’s Techno Blast move so it becomes Electric type.",
                "ja": "ゲノセクトに　もたせると　テクノバスターという　わざが　でんきタイプになる　カセット。",
                "es": "Cartucho que convierte Tecno Shock de Genesect en un movimiento de tipo Eléctrico.",
                "fr": "Tenu par Genesect, ce module change la capacité Techno-Buster en une capacité de type Électrik.",
                "de": "Gibt man es Genesect zum Tragen, wandelt es den Typ der Attacke Techblaster in Elektro um.",
            ]),
        "snowball": Entry(appOriginalLanguages: [],
            names: ["ko": "눈덩이", "en": "Snowball", "ja": "ゆきだま", "es": "Bola de Nieve", "fr": "Boule de Neige", "de": "Schneeball"],
            texts: [
                "ko": "단 한 번 쓰면 없어지는 눈덩이. 지니게 하고 얼음 기술을 받으면 공격이 올라간다.",
                "en": "An item to be held by a Pokémon. It boosts Attack if the holder is hit with an Ice-type attack. It can only be used once.",
                "ja": "つかいすての　ゆきだま。　もたせて　こおりの　わざを　うけると　こうげきが　あがる。",
                "es": "Objeto de un solo uso. Aumenta el Ataque del Pokémon que lo lleva si este recibe un ataque de tipo Hielo.",
                "fr": "Objet à tenir. Une boule de neige à usage unique qui augmente l’Attaque du porteur lorsqu’il encaisse une attaque de type Glace.",
                "de": "Wird der Träger von einer Eis-Attacke getroffen, steigt sein Angriff und das Item verschwindet.",
            ]),
        "soul-dew": Entry(appOriginalLanguages: [],
            names: ["ko": "마음의물방울", "en": "Soul Dew", "ja": "こころのしずく", "es": "Rocío Bondad", "fr": "Rosée Âme", "de": "Seelentau"],
            texts: [
                "ko": "라티오스나 라티아스에게 지니게 하면 에스퍼와 드래곤타입 기술의 위력이 올라가는 이상한 구슬.",
                "en": "A wondrous orb to be held by either Latios or Latias. It raises the power of Psychic- and Dragon-type moves.",
                "ja": "ラティオスや　ラティアスに　もたせると　エスパーと　ドラゴンタイプの　わざの　いりょくが　あがる　ふしぎな　たま。",
                "es": "Un orbe fantástico que debe llevar Latios o Latias. Potencia los movimientos de tipo Psíquico y Dragón.",
                "fr": "Objet à faire tenir à Latios ou Latias. Un orbe prodigieux qui augmente la puissance de leurs capacités de type Psy ou Dragon.",
                "de": "Ein Item, das von Latios oder Latias getragen werden kann. Es erhöht die Stärke von Psycho- und Drachen- Attacken.",
            ]),
        "starf-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "스타열매", "en": "Starf Berry", "ja": "スターのみ", "es": "Baya Arabol", "fr": "Baie Frista", "de": "Krambobeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 능력 중의 하나가 크게 올라간다.",
                "en": "A Berry to be consumed by Pokémon. If a Pokémon holds one, one of its stats will sharply increase when it’s in a pinch.",
                "ja": "ポケモンに　もたせると　ピンチのとき　どれか　１つの　のうりょくが　ぐーんと　あがる。",
                "es": "Si la lleva un Pokémon, aumenta mucho una característica en un momento de apuro.",
                "fr": "Tenue, cette Baie augmente beaucoup une des stats en cas de besoin.",
                "de": "Als getragenes Item erhöht diese Beere einen Statuswert des Pokémon stark, sobald es in einer Notlage steckt.",
            ]),
        "steel-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "강철주얼", "en": "Steel Gem", "ja": "はがねのジュエル", "es": "Gema Acero", "fr": "Joyau Acier", "de": "Stahljuwel"],
            texts: [
                "ko": "강철타입의 주얼. 지니게 하면 한 번만 강철 기술의 위력이 강해진다.",
                "en": "A gem with an essence of steel. When held, it strengthens the power of a Steel-type move one time.",
                "ja": "はがねの　タイプの　ジュエル。　もたせると　いちどだけ　はがねの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Acero. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Acier.",
                "de": "Ein Juwel vom Typ Stahl. Es erhöht einmalig die Stärke einer Attacke vom Typ Stahl.",
            ]),
        "steel-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "스틸메모리", "en": "Steel Memory", "ja": "スチールメモリ", "es": "Disco Acero", "fr": "ROM Acier", "de": "Stahl-Disc"],
            texts: [
                "ko": "강철타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Steel-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "はがねタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Acero. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Acier. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Stahl. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "stick": Entry(appOriginalLanguages: [],
            names: ["ko": "대파", "en": "Leek", "ja": "ながねぎ", "es": "Puerro", "fr": "Poireau", "de": "Lauchstange"],
            texts: [
                "ko": "매우 길고 단단한 줄기. 파오리에게 지니게 하면 기술이 급소에 맞기 쉬워진다.",
                "en": "An item to be held by Farfetch’d. This very long and stiff stalk of leek boosts its critical-hit ratio.",
                "ja": "とても　ながくて　かたい　クキ。　カモネギに　もたせると　わざが　きゅうしょに　あたりやすくなる。",
                "es": "Es un puerro muy largo que debe llevar Farfetch’d. Aumenta mucho la probabilidad de que logre un golpe crítico.",
                "fr": "Objet à faire tenir à Canarticho. Un poireau très long et solide qui augmente son taux de critiques.",
                "de": "Ein Item, das von Porenta getragen werden kann. Diese lange Lauchstange erhöht die Volltrefferquote stark.",
            ]),
        "sticky-barb": Entry(appOriginalLanguages: [],
            names: ["ko": "끈적끈적바늘", "en": "Sticky Barb", "ja": "くっつきバリ", "es": "Toxiestrella", "fr": "Piquants", "de": "Klettdorn"],
            texts: [
                "ko": "지니게 하면 매 턴 데미지를 입는다. 자신에게 접촉해온 상대에게 들러붙기도 한다.",
                "en": "An item to be held by a Pokémon. It damages the holder every turn and may latch on to Pokémon that touch the holder.",
                "ja": "もたせると　まいターン　ダメージを　うける。　じぶんに　ふれてきた　あいてに　くっつくことも　ある。",
                "es": "Daña en cada turno al Pokémon que la lleva. Puede adherirse al Pokémon que alcance con su ataque al portador.",
                "fr": "Objet à tenir. Blesse le porteur à chaque tour. Peut s’accrocher aux ennemis qui attaquent le porteur.",
                "de": "Ein Item zum Tragen. Schadet dem Träger in jeder Runde, kann aber an Angreifern haften bleiben, die ihn berühren.",
            ]),
        "terrain-extender": Entry(appOriginalLanguages: [],
            names: ["ko": "그라운드코트", "en": "Terrain Extender", "ja": "グランドコート", "es": "Cubresuelos", "fr": "Champ’Duit", "de": "Feldbeschichtung"],
            texts: [
                "ko": "지니게 한 포켓몬이 기술이나 특성으로 필드를 사용했을 때 여느 때보다 긴 시간 동안 지속된다.",
                "en": "An item to be held by a Pokémon. It extends the duration of the terrain caused by the holder’s move or Ability.",
                "ja": "もたせた　ポケモンが　わざや　とくせいで　フィールドを　はったとき　いつもよりも　ながく　のこる。",
                "es": "Al llevarlo, prolonga la duración de los campos creados por el Pokémon en el terreno de combate mediante movimientos o su habilidad.",
                "fr": "Objet à tenir. Prolonge la durée des champs que le Pokémon peut créer sur le terrain avec une capacité ou un talent.",
                "de": "Ein Item zum Tragen. Hat der Träger durch eine Attacke oder eine Fähigkeit ein Feld erzeugt, verlängert sich dessen Dauer.",
            ]),
        "thick-club": Entry(appOriginalLanguages: [],
            names: ["ko": "굵은뼈", "en": "Thick Club", "ja": "ふといホネ", "es": "Hueso Grueso", "fr": "Masse Os", "de": "Kampfknochen"],
            texts: [
                "ko": "무언가의 단단한 뼈. 탕구리 혹은 텅구리에게 지니게 하면 공격이 올라간다.",
                "en": "An item to be held by Cubone or Marowak. It’s a hard bone of some sort that boosts the Attack stat.",
                "ja": "なにかの　かたい　ホネ。　カラカラ　または　ガラガラに　もたせると　こうげきが　あがる。",
                "es": "Un extraño tipo de hueso que potencia los ataques físicos de Cubone y Marowak cuando lo llevan.",
                "fr": "Objet à faire tenir à Osselait ou Ossatueur. Un os dur qui augmente leur Attaque.",
                "de": "Ein harter Knochen, der den Angriffs-Wert von Tragosso oder Knogga erhöht, wenn sie ihn tragen.",
            ]),
        "throat-spray": Entry(appOriginalLanguages: [],
            names: ["ko": "목스프레이", "en": "Throat Spray", "ja": "のどスプレー", "es": "Espray Bucal", "fr": "Spray Gorge", "de": "Halsspray"],
            texts: [
                "ko": "소리 기술을 사용하면 특수공격이 올라간다.",
                "en": "Raises Sp. Atk when a Pokémon uses a sound-based move.",
                "ja": "おとに　かんする　わざを　つかうと　とくこうが　あがる。",
                "es": "Aumenta el Ataque Especial al emplear un movimiento que se sirva del sonido.",
                "fr": "Augmente l’Attaque Spéciale du porteur lorsqu’il utilise une capacité basée sur le son.",
                "de": "Erhöht bei Einsatz einer Lärm-Attacke den Spezial-Angriff.",
            ]),
        "utility-umbrella": Entry(appOriginalLanguages: [],
            names: ["ko": "만능우산", "en": "Utility Umbrella", "ja": "ばんのうがさ", "es": "Parasol Multiuso", "fr": "Parapluie Solide", "de": "Allzweckschirm"],
            texts: [
                "ko": "지니게 한 포켓몬은 비와 햇살이 강할 때의 영향을 받지 않게 된다.",
                "en": "An item to be held by a Pokémon. This sturdy umbrella protects the holder from the effects of rain and harsh sunlight.",
                "ja": "もたせた　ポケモンは　あめと　ひざしがつよいときの　えいきょうを　うけなくなる。",
                "es": "El portador se vuelve invulnerable a los efectos de la lluvia y del sol.",
                "fr": "Objet à tenir. Protège le porteur des effets de la pluie et des rayons du soleil.",
                "de": "Der Träger ist gegen die Effekte von Regen und starkem Sonnenlicht geschützt.",
            ]),
        "water-gem": Entry(appOriginalLanguages: [],
            names: ["ko": "물주얼", "en": "Water Gem", "ja": "みずのジュエル", "es": "Gema Agua", "fr": "Joyau Eau", "de": "Wasserjuwel"],
            texts: [
                "ko": "물타입의 주얼. 지니게 하면 한 번만 물 기술의 위력이 강해진다.",
                "en": "A gem with an essence of water. When held, it strengthens the power of a Water-type move one time.",
                "ja": "みずの　タイプの　ジュエル。　もたせると　いちどだけ　みずの　わざの　いりょくが　つよまる。",
                "es": "Joya de un solo uso que potencia los movimientos de tipo Agua. Debe llevarla un Pokémon.",
                "fr": "Objet à tenir. Un joyau augmentant une fois la puissance des capacités de type Eau.",
                "de": "Ein Juwel vom Typ Wasser. Es erhöht einmalig die Stärke einer Attacke vom Typ Wasser.",
            ]),
        "water-memory": Entry(appOriginalLanguages: [],
            names: ["ko": "워터메모리", "en": "Water Memory", "ja": "ウオーターメモリ", "es": "Disco Agua", "fr": "ROM Eau", "de": "Wasser-Disc"],
            texts: [
                "ko": "물타입의 데이터가 들어 있는 메모리. 특정 포켓몬이 지니면 타입이 바뀐다.",
                "en": "A memory disc that contains Water-type data. It changes the type of the holder if held by a certain species of Pokémon.",
                "ja": "みずタイプの　データが　はいった　メモリ。　とくていの　ポケモンが　もつと　タイプが　かわる。",
                "es": "Disco de datos que contiene información relativa al tipo Agua. Permite cambiar de tipo a cierto Pokémon.",
                "fr": "Une carte mémoire contenant des données sur le type Eau. Un certain Pokémon peut changer de type en l’équipant.",
                "de": "Eine Disc mit Daten zum Typ Wasser. Sie löst bei einem bestimmten Pokémon einen Typenwechsel aus.",
            ]),
        "wave-incense": Entry(appOriginalLanguages: [],
            names: ["ko": "잔물결향로", "en": "Wave Incense", "ja": "さざなみのおこう", "es": "Incienso Acua", "fr": "Encens Vague", "de": "Wellenrauch"],
            texts: [
                "ko": "이상한 향기의 향로. 지니게 하면 물타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. This incense has a curious aroma that boosts the power of Water-type moves.",
                "ja": "ふしぎな　かおりの　おこう。　もたせると　みずタイプの　わざの　いりょくが　あがる。",
                "es": "Tiene un curioso aroma que potencia los movimientos de tipo Agua. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Un encens au parfum curieux augmentant la puissance des capacités de type Eau.",
                "de": "Ein Item zum Tragen. Dieses exotische Duftkraut verstärkt Attacken vom Typ Wasser.",
            ]),
        "wiki-berry": Entry(appOriginalLanguages: [],
            names: ["ko": "위키열매", "en": "Wiki Berry", "ja": "ウイのみ", "es": "Baya Wiki", "fr": "Baie Wiki", "de": "Wikibeere"],
            texts: [
                "ko": "포켓몬에게 지니게 하면 위급할 때 HP를 회복한다. 싫어하는 맛이면 혼란에 빠진다.",
                "en": "If held by a Pokémon, it restores the user’s HP in a pinch, but it will cause confusion if the user hates the taste.",
                "ja": "ポケモンに　もたせると　ピンチのとき　ＨＰを　かいふくする。　きらいな　あじだと　こんらん　する。",
                "es": "Los Pokémon pueden llevarla o usarla para restaurar algunos PS. Su sabor puede causar confusión si no les gusta.",
                "fr": "Tenue, cette Baie restaure des PV en cas de besoin, mais rend le Pokémon confus si son goût lui déplaît.",
                "de": "Als getragenes Item füllt die Beere im Notfall die KP eines Pokémon auf, doch ihr Aroma verwirrt jene, die es nicht mögen.",
            ]),
        "zoom-lens": Entry(appOriginalLanguages: [],
            names: ["ko": "포커스렌즈", "en": "Zoom Lens", "ja": "フォーカスレンズ", "es": "Telescopio", "fr": "Lentille Zoom", "de": "Zoomlinse"],
            texts: [
                "ko": "지니게 한 포켓몬이 상대보다도 행동하는 것이 늦을 때 기술이 명중하기 쉬워진다.",
                "en": "An item to be held by a Pokémon. If the holder moves after its target moves, its accuracy will be boosted.",
                "ja": "もたせた　ポケモンが　あいてよりも　こうどうするのが　おそいとき　わざが　めいちゅう　しやすくなる。",
                "es": "Debe llevarlo un Pokémon. Si se mueve después del enemigo, aumenta la Precisión del Pokémon.",
                "fr": "Objet à tenir. Augmente la Précision du porteur s’il attaque après l’ennemi.",
                "de": "Ein Item zum Tragen. Agiert das Ziel zuerst, erhöht sich die Genauigkeit des Trägers.",
            ]),
        "venusaurite": Entry(appOriginalLanguages: [],
            names: ["ko": "이상해꽃나이트", "en": "Venusaurite", "ja": "フシギバナイト", "es": "Venusaurita", "fr": "Florizarrite", "de": "Bisaflornit"],
            texts: [
                "ko": "이상해꽃에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.",
                "en": "One of a variety of mysterious Mega Stones. Have Venusaur hold it, and this stone will enable it to Mega Evolve during battle.",
                "ja": "フシギバナに　もたせておくと　たたかいのとき　メガシンカが　できる　ふしぎな　メガストーンの　いっしゅ。",
                "es": "Una de las misteriosas Megapiedras. Permite megaevolucionar a Venusaur en combate.",
                "fr": "Une variété de Méga-Gemme. Tenue par un Florizarre, elle lui permet de méga-évoluer durant un combat.",
                "de": "Einer der mysteriösen Mega-Steine. Wird er von einem Bisaflor getragen, kann es im Kampf eine Mega-Entwicklung durchführen.",
            ]),
        "charizardite-x": Entry(appOriginalLanguages: [],
            names: ["ko": "리자몽나이트X", "en": "Charizardite X", "ja": "リザードナイトＸ", "es": "Charizardita X", "fr": "Dracaufite X", "de": "Gluraknit X"],
            texts: [
                "ko": "리자몽에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.",
                "en": "One of a variety of mysterious Mega Stones. Have Charizard hold it, and this stone will enable it to Mega Evolve during battle.",
                "ja": "リザードンに　もたせておくと　たたかいのとき　メガシンカが　できる　ふしぎな　メガストーンの　いっしゅ。",
                "es": "Una de las misteriosas Megapiedras. Permite megaevolucionar a Charizard en combate.",
                "fr": "Une variété de Méga-Gemme. Tenue par un Dracaufeu, elle lui permet de méga-évoluer durant un combat.",
                "de": "Einer der mysteriösen Mega-Steine. Wird er von einem Glurak getragen, kann es im Kampf eine Mega-Entwicklung durchführen.",
            ]),
        "charizardite-y": Entry(appOriginalLanguages: [],
            names: ["ko": "리자몽나이트Y", "en": "Charizardite Y", "ja": "リザードナイトＹ", "es": "Charizardita Y", "fr": "Dracaufite Y", "de": "Gluraknit Y"],
